import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../store'
import { requestAIAgentParams } from './types/params.type'
import { ApiResponse } from './types/response.type'

const requestAIAgent = async (params: requestAIAgentParams): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/aiagent`,
                    params: {
                        method: 'POST',
                          headers: {
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify(params)
                    }
                }
            },
            callback
        )
    })
}

export default requestAIAgent
