export function renderImageFromBlob(imageBlob) {
    return new Promise((resolve, reject) => {
        const img = new Image()
        const canvas = document.createElement('canvas')
        const ctx = canvas.getContext('2d')

        // Load the image from the Blob
        const objectURL = URL.createObjectURL(imageBlob)
        img.onload = () => {
            URL.revokeObjectURL(objectURL)

            // Set canvas dimensions to 9:16 aspect ratio
            const maxHeight = 800 // or any height you prefer
            const newWidth = (maxHeight * 9) / 16
            canvas.width = newWidth
            canvas.height = maxHeight

            // Calculate scale and position for object-fit: cover
            const imgAspectRatio = img.width / img.height
            const canvasAspectRatio = canvas.width / canvas.height
            let drawWidth, drawHeight, offsetX, offsetY

            if (imgAspectRatio > canvasAspectRatio) {
                drawHeight = canvas.height
                drawWidth = drawHeight * imgAspectRatio
                offsetX = (canvas.width - drawWidth) / 2
                offsetY = 0
            } else {
                drawWidth = canvas.width
                drawHeight = drawWidth / imgAspectRatio
                offsetX = 0
                offsetY = (canvas.height - drawHeight) / 2
            }

            // Draw the image onto the canvas
            ctx.clearRect(0, 0, canvas.width, canvas.height)
            ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight)

            resolve(canvas.toDataURL()) // Return the canvas data URL or you can use canvas directly
        }
        img.onerror = err => {
            URL.revokeObjectURL(objectURL)
            reject(err)
        }
        img.src = objectURL
    })
}

export function dataURLToStream(dataURL) {
    return new Promise((resolve, reject) => {
        const img = new Image()
        const canvas = document.createElement('canvas')
        const ctx = canvas.getContext('2d')

        img.onload = () => {
            canvas.width = img.width
            canvas.height = img.height

            ctx.drawImage(img, 0, 0)

            // Create and resolve the media stream
            resolve(canvas.captureStream())
        }

        img.onerror = err => {
            reject(err)
        }

        img.src = dataURL
    })
}

const MAX_SEND_SNAP_ATTEMPTS = 3

export const sendSnap = async (snapUrl: string) => {
    if (!snapUrl) return
    let attempt = 0
    while (attempt < MAX_SEND_SNAP_ATTEMPTS) {
        attempt++
        const imageUrl = getSnapSource(snapUrl)

        try {
            localStorage.removeItem(IS_LIVE_SNAP_LOADED)
            console.log('send snap action started')

            const response = await fetch(imageUrl)

            if (response.status !== 200) {
                throw new Error('Unable to fetch image')
            }
            const blob = await response.blob()

            if (cameraHadLoad) {
                window.postMessage(
                    {
                        action: ServiceMessageName.SendSnapBlob,
                        data: { blob: blob }
                    },
                    '*'
                )
            }

            const cameraBtnClass = '.jh13h .cDumY.EQJi_'
            const cameraBtn = (await Utils.waitForElement(
                cameraBtnClass,
                'camera btn',
                5000
            )) as HTMLButtonElement

            if (!cameraBtn) {
                throw new Error('Camera btn not found')
            } else {
                cameraBtn.click()
            }

            const cameraNotLoadedClass = (await Utils.waitForElement(
                '.CYQZP .mPxJQ.OqR8V .kbgiH .tPHQ9.v0HEU .nonIntl',
                'camera btn',
                3000
            )) as HTMLButtonElement

            const warningBar: HTMLSpanElement = cameraNotLoadedClass

            const submitButtonClass = 'form.tvul8 button[type="submit"]'
            const sendButtonClass = '.YatIx.fGS78.eKaL7.Bnaur'

            if (document.querySelector(submitButtonClass)) {
                throw new Error('Old feed load')
            } else {
                const sendBtn = document.querySelector(sendButtonClass)
                if (sendBtn) {
                    throw new Error('Old feed load')
                }
            }
            if (
                !cameraHadLoad ||
                (warningBar && warningBar.innerText === 'Could not load camera.')
            ) {
                const dataURL = await renderImageFromBlob(blob)

                const spoofStream = await dataURLToStream(dataURL)

                const video = document.querySelector('#local-video') as HTMLVideoElement
                try {
                    if (video) {
                        video.srcObject = spoofStream as MediaProvider
                        video.muted = true
                        await video.play()
                        console.log('Video is playing')
                    } else {
                        throw new Error('No video element found')
                    }
                } catch (err) {
                    throw new Error(err)
                }
            } else {
                await new Promise<void>((resolve, reject) => {
                    let timeElapsed = 0
                    const checkSpoofedStream = () => {
                        const isSnapLoaded = localStorage.getItem(IS_LIVE_SNAP_LOADED)
                        if (isSnapLoaded) {
                            resolve()
                        } else {
                            timeElapsed += 300
                            if (timeElapsed < 10000) {
                                setTimeout(checkSpoofedStream, 300)
                            } else {
                                reject(new Error(`Issue loading snap`))
                            }
                        }
                    }
                    checkSpoofedStream()
                })
            }

            const shotButtonClass = '.UEYhD .gK0xL'
            const shotButton = (await Utils.waitForElement(
                shotButtonClass,
                'shot_button'
            )) as HTMLButtonElement
            if (!shotButton) {
                throw new Error('Shot btn not found')
            } else {
                shotButton.click()
            }

            const submitButton = (await Utils.waitForElement(
                submitButtonClass,
                'submit_snap_button',
                2000
            )) as HTMLButtonElement

            if (!submitButton) {
                const sendToBtn = (await Utils.waitForElement(
                    sendButtonClass,
                    'send to btn'
                )) as HTMLButtonElement

                if (sendToBtn) {
                    sendToBtn.click()
                    await Utils.sleep(1000)
                }
                const submitButtonAwait = (await Utils.waitForElement(
                    submitButtonClass,
                    'submit_snap_button'
                )) as HTMLButtonElement
                if (!submitButtonAwait) {
                    throw new Error('Submit btn not found')
                } else {
                    await Utils.sleep(1000)
                    submitButtonAwait.click()
                }
            } else {
                await Utils.sleep(1000)
                submitButton.click()
            }
            await Utils.sleep(1000)
            return
            // if (!dispatchOpennerMessage) {
            //     await API.syncCustomBotMessage({
            //         snapchat_account_id: userMainInfo.mutable_username,
            //         request_user_id: currentOpenChatUser.uuid,
            //         snap_sent_id: snapUrl,
            //         select_preset_id: `${currentSBPreset.id}`
            //     })
            // }
        } catch (error) {
            console.error('@@@@ send snap error', error)
            const closedSuccess = await closeSendingSnap()
            console.log('@@@@ closedSuccess', closedSuccess)
        } finally {
            localStorage.removeItem(IS_LIVE_SNAP_LOADED)
        }
    }
}

export const getSpecificSnapsUrl = (snapIds: string[], botCurrentChatDay = 1) => {
    const snaps = filterOutfitSnaps(botCurrentChatDay)

    if (snaps && snaps.length > 0) {
        return snaps.reduce((prev, curr) => {
            if (snapIds.includes(curr.id)) {
                prev.push(curr.snapUrl)
            }
            return prev
        }, []) as string[]
    }

    return []
}

const getUnusedSnapId = async (params: getUnusedParamsType) => {
    const res = await API.getUnusedSnap(params)

    if (res.status && res.data.snap_id) {
        return res.data.snap_id
    }
    return null
}

export const getUnusedSnap = async (snapList: string[]) => {
    const id = await getUnusedSnapId({
        request_user_id: currentOpenChatUser.uuid,
        snap_ids_list: snapList,
        snapchat_account_id: userMainInfo.mutable_username
    })

    return id
}

const closeSendingSnap = async () => {
    let closeSuccessfully = false
    const closeButtonClass = '.acEGc .aTkGG .MQv99 button.AJ_5h'
    const closeButton = (await Utils.waitForElement(
        closeButtonClass,
        'close_Sent_Snap'
    )) as HTMLButtonElement
    if (closeButton) {
        closeButton?.click()
        closeSuccessfully = true
    } else {
        const smallScreenBackBtnClass = '.OgvuO button.tTyKn'
        const backBtnClass = '.KHnKO button.STlkX'

        const backBtn = (await Utils.waitForElement(backBtnClass, 'back_btn')) as HTMLButtonElement

        if (backBtn) {
            backBtn?.click()

            const closeButton = (await Utils.waitForElement(
                closeButtonClass,
                'close_Sent_Snap'
            )) as HTMLButtonElement
            if (closeButton) {
                closeButton?.click()
                closeSuccessfully = true
            }
        } else {
            const smallScreenBackBtn = (await Utils.waitForElement(
                smallScreenBackBtnClass,
                'small_screen_back_btn'
            )) as HTMLButtonElement

            if (smallScreenBackBtn) {
                smallScreenBackBtn?.click()
                const backBtn = (await Utils.waitForElement(
                    backBtnClass,
                    'back_btn'
                )) as HTMLButtonElement

                if (backBtn) {
                    backBtn?.click()

                    const closeButton = (await Utils.waitForElement(
                        closeButtonClass,
                        'close_Sent_Snap'
                    )) as HTMLButtonElement
                    if (closeButton) {
                        closeButton?.click()
                        closeSuccessfully = true
                    }
                }
            }
        }
    }
    await Utils.sleep(1000)
    return closeSuccessfully
}
