import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { ApiResponse } from './types/response.type'
import { authStore } from '../store'

// get chat older than 12 hr but less that 3 days

const getOldConversations = async (ownerId: string, hours: number): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/get_old_conversation?owner_id=${ownerId}&before_hours=${hours}`,
                    params: {
                        method: 'GET',
                        headers: { Authorization: authStore.getAPIKey() }
                    }
                }
            },
            callback
        )
    })
}

export default getOldConversations
