import * as API from '@/scripts/api'
import { bBotRunningStatus, isManualScroll, scrollFeed, userMainInfo } from '../..'
import { processSendOpener } from './processSendOpener'
import { processNewChatMessage } from './processNewChatMessage'
import * as Utils from '@/lib/common'
import { chatUserType } from '@/lib/types/scrape-engine.type'
import { getUserInfoFromElement } from './getUserInfoFromElement'

const feedUserDivClassName =
    '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'


export const processUnloadChat = async (userId: string) => {
    let userInfoArray = []
   


    const runProcessToCheckUserInList = async (userElements: NodeListOf<HTMLDivElement>) => {

        for (let i = 0; i < userElements.length; i++) {
            if (!bBotRunningStatus || isManualScroll) {
                return
            }
            const userInfo = getUserInfoFromElement(userElements[i])
            if (!userInfo) {
                continue
            }

            if (!userInfoArray.some(user => user.uuid === userInfo.uuid)) {
                userInfoArray.push(userInfo)
                if (userId === userInfo.uuid) {
                    const response = await API.checkOpener({
                        request_user_id_list: [userId],
                        snapchat_account_id: userMainInfo.mutable_username
                    })
                
                    if(response.data.length > 0) {
                        await processSendOpener([userElements[i]])
                    } else {
                        await processNewChatMessage([userElements[i]])
                    }
                    
                }
                return true
            }
        }

        return false

    }

    const processWhileScrollToBottom = async () => {
        let totalCount = 0
        let userElements = document.querySelectorAll(
            feedUserDivClassName
        ) as NodeListOf<HTMLDivElement>
        const isInList = await runProcessToCheckUserInList(userElements)

        if (isManualScroll || isInList) {
            return
        }
        while (true) {
            if (!bBotRunningStatus || isManualScroll) {
                return
            }
            totalCount = userInfoArray.length
            userElements = document.querySelectorAll(feedUserDivClassName)

            scrollFeed(false)

            await Utils.sleep(1000)
            userElements = document.querySelectorAll(feedUserDivClassName)

            const isInList = await runProcessToCheckUserInList(userElements)

            // Loop it through till not increase the friends
            if (totalCount == userInfoArray.length || isInList) {
                scrollFeed(true)
                break
            }
        }
    }

    await processWhileScrollToBottom()
}
