// GET CLIENT FROM LICENSE KEY

import { API_ENDPOINT, ServiceMessageName } from "@/lib/constants"
import { ApiResponse } from "./types/response.type"

const getClientInfo = (license_key: string): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/me`,
                    params: {
                        method: 'GET',
                        headers: { Authorization: license_key }
                    }
                }
            },
            callback
        )
    })
}

export default getClientInfo 