import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { ApiResponse } from './types/response.type'
import { authStore } from '../store'
import { updateTodaysAddCounterParams } from './types/params.type'

const updateTodaysAddCounter = (params: updateTodaysAddCounterParams): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/increment_snap_add_counter`,
                    params: {
                        method: 'POST',
                        headers: { Authorization: authStore.getAPIKey() },
                        body: JSON.stringify(params)
                    }
                }
            },
            callback
        )
    })
}

export default updateTodaysAddCounter
