import { ERROR_MSG } from '@/lib/constants'
import { ApiResponse } from './types/response.type'
import { LocalStorage } from '@/lib/chrome-storage'

const getUserFriends = async (): Promise<ApiResponse> => {
    try {
        const authHeaders = await LocalStorage.getItem('FRIENDS_AUTH_HEADERS')

        const headers = {}
        authHeaders.map(_ => {
            headers[_.name] = _.value
        })

        const friendFormData = await LocalStorage.getItem('FRIENDS_FORMDATA')
        let formData: FormData = new FormData()
        Object.keys(friendFormData).forEach(key => {
            friendFormData[key].forEach(value => {
                formData.append(key, value)
            })
        })

        const response = await fetch(`https://web.snapchat.com/ami/friends`, {
            method: 'POST',
            headers: headers,
            body: formData
        })
        if (response.ok) {
            const resData = await response.json()
            return {
                status: true,
                data: resData
            }
        } else {
            throw new Error('Error getting friends list')
        }
    } catch (error) {
        return {
            status: false,
            message: error?.message || ERROR_MSG.SOMETHING_WENT_WRONG
        }
    }
}

export default getUserFriends
