import { LocalStorage } from './chrome-storage'
import { DEFAULT_PRESET_LOCAL_VALUE, SB_LOCAL_PRESET_VALUE } from './constants'
import dayjs from './dayjs'
import { v4 as uuidv4 } from 'uuid'
import { LocallySetPresetValueType } from './types/preset.type'
import { ApiResponse } from '@/scripts/api/types/response.type'

export const getNextTimer = (delay: number) => {
    const utcNow = dayjs.utc()

    const nextTime = utcNow.add(delay, 'minutes').format()

    return nextTime
}

export const isTimePassed = (scheduled: string) => {
    const nowUtc = dayjs.utc()
    const time = dayjs.utc(scheduled)

    return time.isBefore(nowUtc)
}

export const handleParseInt = (value: string) => {
    let intValue = parseInt(value)

    if (isNaN(intValue)) {
        intValue = undefined
    }

    return intValue
}

export const handleKeyDownOnIntegerInput = (event: React.KeyboardEvent<HTMLInputElement>) => {
    const invalidChars = ['-', 'e', 'E', '.']
    if (invalidChars.includes(event.key)) {
        event.preventDefault()
    }
}

export const deviceTimeZone = Intl.DateTimeFormat().resolvedOptions().timeZone

export const getTodaysDateDay = () => {
    const nowUtc = dayjs.utc()

    return nowUtc.date()
}

export const getUniqueID = () => {
    return uuidv4() as string
}

export const matchesString = (str: string, query: string, exact: boolean = false) =>
    exact
        ? str.toLowerCase() === query.trim().toLowerCase()
        : str.toLowerCase().includes(query.trim().toLowerCase())

export const multiLineChat = (text: string) => {
    return text
        .replace(/;/g, '; ')
        .split('|')
        .map(i => i.trim())
        .filter(i => i !== '')
}

// Wait for element Function
export const waitForElement = async (selector: any, element: string, limit: number = 5000) => {
    return new Promise(resolve => {
        const startTime = Date.now() // Record the start time

        const validate = () => {
            const element = document.querySelector(selector)
            const elapsedTime = Date.now() - startTime

            if (element) {
                clearInterval(interval)
                resolve(element) // Resolve with the found element
            } else if (elapsedTime > limit) {
                // Check if the elapsed time exceeded the limit
                clearInterval(interval)
                resolve(null)
            }
        }

        const interval = setInterval(validate, 100)
        validate()

        // Optional: If you want to make sure that the function always either resolves or rejects
        setTimeout(() => {
            clearInterval(interval)

            // console.log(`Element not found within ${limit} ms, ${element}`);
            resolve(null)
        }, limit)
    })
}

export const sleep = (ms: number) => {
    return new Promise((resolve, reject) => {
        setTimeout(resolve, ms)
    })
}

export const shuffleArray = <T>(array: T[]): T[] => {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[array[i], array[j]] = [array[j], array[i]]
    }
    return array
}

export const getRandomNumberInRange = (min: number, max: number) => {
    return Math.floor(Math.random() * (max - min + 1)) + min
}

export const getBelowRandomNumber = (number: number) => {
    return Math.floor(Math.random() * number)
}

