export const waitForElementUnload = async (selector: any) => {
    return new Promise(resolve => {
        const validate = () => {
            const element = document.querySelector(selector)
            if (!element) {
                clearInterval(interval)
                resolve(true) // Resolve with true when the element is unloaded
            }
        }

        const interval = setInterval(validate, 100)
        validate()
    })
}


export const waitForElementUnloadWithTimeout = async (selector: any, timeout: number) => {
    return Promise.race([
        waitForElementUnload(selector),
        new Promise((resolve, _) => setTimeout(() => resolve(false), timeout))
    ])
}

export const waitForElementTillLoad = async (selector: any) => {
    return new Promise(resolve => {
        const validate = () => {
            const element = document.querySelector(selector)

            if (element) {
                clearInterval(interval)
                resolve(element) // Resolve with the found element
            }
        }

        const interval = setInterval(validate, 100)
        validate()
    })
}

export function formatCapitalizeString(input: string) {
    // Split the string by underscores
    const words = input.split('_')

    // Capitalize the first letter of each word
    const capitalizedWords = words.map(
        word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
    )

    // Join the words back into a single string without underscores
    return capitalizedWords.join(' ')
}

export const setLocalPresetValue = async (updateValues: Partial<LocallySetPresetValueType>) => {
    const value = {
        ...DEFAULT_PRESET_LOCAL_VALUE,
        ...(await LocalStorage.getItem(SB_LOCAL_PRESET_VALUE))
    }

    await LocalStorage.setItem(SB_LOCAL_PRESET_VALUE, { ...value, ...updateValues })
}

export async function callApiWithRetries(apiCall: () => Promise<ApiResponse>, retries = 3) {
    let response
    for (let i = 0; i < retries; i++) {
        response = await apiCall()
        if (response.status) {
            return response
        }
        await sleep(5000)
        // Optionally handle specific error messages or conditions here
    }
    throw new Error(response?.message ?? 'API call failed after multiple attempts.')
}
