var lastProcessedOpponentMsg = ''

// will return number greater than zero if find user typing
const waitTillUserTyping = async (userElement: HTMLDivElement) => {
    let checkTypingAttempt = 0
    const chatArea = document.querySelector('._XMCw .ChLAv')

    do {
        if (!bBotRunningStatus) {
            return
        }
        const typingSign = chatArea?.querySelector('.RGJQE')
        const rect = typingSign?.getClientRects()

        if (rect && rect.length > 0) {
            const firstRect = rect[0]

            const height = firstRect.height
            const width = firstRect.width

            const chatStatusElement: HTMLSpanElement = userElement.querySelector('.GQKvA .nonIntl')

            const isStatusTyping = chatStatusElement?.innerText
                .toLowerCase()
                .replace(/\s/g, '')
                .includes('typing')

            if ((height === 0 && width === 0) || (height > 40 && width > 40) || !isStatusTyping) {
                return checkTypingAttempt
            }
        } else {
            return checkTypingAttempt
        }

        await Utils.sleep(500)
        checkTypingAttempt++
    } while (true)
}

const processSeeSnaps = async () => {
    do {
        const element = checkUserPresentInCurrentFeed()

        if (!element) {
            throw new Error('User not found in feed')
        }
        const viewSnapButton = element.querySelector('.w15C2 .HEkDJ.VKjn5') as HTMLDivElement

        const hasViewButton = element.querySelector('.w15C2') as HTMLDivElement
        const is_new_snap = hasViewButton
            ? hasViewButton.innerText.toLowerCase().replace(/\s/g, '').includes('view')
            : false

        if (!bBotRunningStatus) {
            return
        }
        if (viewSnapButton && is_new_snap) {
            viewSnapButton.click()

            const loadSnapArea = await Utils.waitForElement('.vDdE2.hJysT', 'snap area')
            console.log(
                '#### processSeeSnaps loadSnapArea',
                loadSnapArea,
                '>>>>>',
                currentOpenChatUser.userName,
                is_new_snap
            )
            if (!loadSnapArea) {
                return false
            }

            const success = await waitForContentToLoad()

            if (!success) {
                const noLongerViewing = checkNoLongerViewingLoaded()
                if (noLongerViewing) {
                    window.location.reload()
                    return false
                }
            }

            const loadError = await document.querySelector('.Fpg8t .VqwkQ .c12IS .tPHQ9.v0HEU')
            console.log(
                '#### processSeeSnaps loadError',
                currentOpenChatUser.userName,
                '>>>>>',
                loadError
            )

            if (loadError) {
                await Utils.sleep(1000)
                return false
            } else {
                await Utils.sleep(3000)
            }

            const closeButton = document.querySelector('.ecBYF .Hb2_Z .h9IpV') as HTMLButtonElement

            if (closeButton) {
                closeButton.click()
            }
            await Utils.sleep(3000)
        } else {
            return true
        }
    } while (true)
}

export const processNewChatMessage = async (userElements: HTMLDivElement[]) => {
    for (let userElement of userElements) {
        if (!bBotRunningStatus) {
            return
        }
        const userInfo = getUserInfoFromElement(userElement)

        if (userInfo) {
            if (delayedChatUserDisplayName.includes(userInfo.userName)) return
            await checkChatConversationStatus(userInfo.uuid, userInfo.userName)

            if (cacheDisableChatUser[userInfo.uuid]) {
                continue
            }

            setCurrentChatUser(userInfo)
            if (userInfo.is_new_snap) {
                try {
                    const openSnapSuccessfully = await processSeeSnaps()
                    updateFailedLoadingSnap(userInfo.uuid, !openSnapSuccessfully)
                    if (!openSnapSuccessfully && !userInfo.is_new_chat) {
                        continue
                    }
                } catch (err) {
                    continue
                }
            }
            if (!bBotRunningStatus) {
                return
            }
            const isUserPresentInFeed = checkUserPresentInCurrentFeed()
            if (!isUserPresentInFeed) {
                continue
            }
            const statusElm: HTMLSpanElement = isUserPresentInFeed.querySelector('.GQKvA .nonIntl')

            statusElm.click()
            await respondWithAI(isUserPresentInFeed)
        }
    }
}

const doubleCheckNewMessage = async () => {
    const chatMessage = await scrapeChatHistory(true)
    let lastCombinedText = handleCombineMultiChat(chatMessage)

    if (typeof lastCombinedText !== 'string') {
        return true
    }

    console.log('@@@@@@@ ----> ', lastCombinedText, lastProcessedOpponentMsg)

    if (lastCombinedText?.trim() !== lastProcessedOpponentMsg?.trim()) {
        return true
    }
    return false
}

const respondWithAI = async (userElement: HTMLDivElement) => {
    lastProcessedOpponentMsg = ''
    let avoidLastMessage = false
    let receivedNewMessageWhileOpenChat = false
    let aiResponse = null
    do {
        do {
            let chatMessage = await scrapeChatHistory()
            await waitTillUserTyping(userElement)
            // axg, there might be new message
            chatMessage = await scrapeChatHistory(true)
            await LocalStorage.setItem(KEY_NEW_MESSAGE_IN_CONVERSATION, false)
            const startTime = performance.now()
            aiResponse = await requestAIChat(chatMessage, avoidLastMessage)
            const endTime = performance.now()

            setAiagentExecutionTime(endTime - startTime)

            // if cta is sent, will not wait for other msg and send cta immediately
            if (aiResponse.status && aiResponse.data?.action?.flag_cta_sent) break
            await waitTillUserTyping(userElement)

            const hasNewMessage = await LocalStorage.getItem(KEY_NEW_MESSAGE_IN_CONVERSATION)
            if (!!hasNewMessage) {
                receivedNewMessageWhileOpenChat = await doubleCheckNewMessage()
            } else {
                receivedNewMessageWhileOpenChat = false
            }
            await LocalStorage.setItem(KEY_NEW_MESSAGE_IN_CONVERSATION, false)
            avoidLastMessage = true
        } while (receivedNewMessageWhileOpenChat)

        if (aiResponse.status) {
            await processAIResponse(aiResponse.data)
        }
        await waitTillUserTyping(userElement)
        const hasNewMessage = await LocalStorage.getItem(KEY_NEW_MESSAGE_IN_CONVERSATION)
        if (!!hasNewMessage) {
            receivedNewMessageWhileOpenChat = await doubleCheckNewMessage()
        } else {
            receivedNewMessageWhileOpenChat = false
        }
        await LocalStorage.setItem(KEY_NEW_MESSAGE_IN_CONVERSATION, false)
        avoidLastMessage = false
    } while (receivedNewMessageWhileOpenChat)

    const hasNewMessage = await LocalStorage.getItem(KEY_NEW_MESSAGE_IN_CONVERSATION)

    if (hasNewMessage) {
        await respondWithAI(userElement)
    } else {
        await closeCurrentChat()
    }
}

const requestAIChat = async (messages: threadMessageType[], avoidedLastCall = false) => {
    const clonedMessages = cloneDeep(messages)
    if (clonedMessages.length === 0) return { status: false }

    console.log(`lastMessage given from ${currentOpenChatUser.userName}`)

    let lastCombinedText = handleCombineMultiChat(messages)

    if (typeof lastCombinedText !== 'string') {
        if (currentChatConversationStatus.final_static_message_is_sent) {
            return { status: false }
        }
        const res = await API.snapResponse({
            request_user_id: currentOpenChatUser.uuid,
            snapchat_account_id: userMainInfo.mutable_username
        })

        if (res.status) {
            return res
        } else {
            return { status: false }
        }
    }

    if (
        !avoidedLastCall &&
        lastCombinedText.includes(lastProcessedOpponentMsg) &&
        lastProcessedOpponentMsg
    ) {
        lastCombinedText = lastCombinedText.split(lastProcessedOpponentMsg)[1]
    }

    lastCombinedText = lastCombinedText
        .trim()
        .replace(/^(\|)|(\|)$/g, '')
        .trim()

    if (lastCombinedText?.trim() === '') {
        console.log('Capture empty message')
        return {
            status: false
        }
    }

    lastProcessedOpponentMsg = lastCombinedText?.trim()

    const { details = {}, id } = currentSBPreset
    const { cta } = details
    const { cta: save_cta } = currentChatConversationStatus ?? {}
    let derivedCtaInfo = null
    let derivedFreeTrialInfo = null

    if (save_cta && save_cta.link && save_cta.platform) {
        derivedCtaInfo = save_cta
    } else {
        derivedCtaInfo = await getRandomCTA()
    }

    const params: requestAIAgentParams = {
        user_setting: {
            name: currentOpenChatUser.userName,
            uid: currentOpenChatUser.uuid
        },
        bot_setting: {
            name: details.name,
            age: details.age,
            model_info: details.modelInfo,
            cta_info: {
                platform: derivedCtaInfo?.platform,
                link: derivedCtaInfo?.link
            },
            // cta_message: cta?.ctaMessage?.bDefaultCtaMessage
            //     ? `i wanna continue this but i cant send anything too dirty here otherwise my snapchat could get banned just message me on my ${derivedCtaInfo?.platform} ${derivedCtaInfo?.link}`
            //     : cta.ctaMessage?.message
            //           ?.replaceAll('{platform}', derivedCtaInfo?.platform)
            //           ?.replaceAll('{link}', derivedCtaInfo?.link),
            daytime_setting: details.dayTimeSetting,
            nighttime_setting: details.nightTimeSetting,
            language: 'en',
            source: details.source
        },
        frontend_bot_setting: {
            city: details.city,
            timezone: details.timezone,
            match_user_location: details.matchUsersLocation
        },
        user_message: lastCombinedText,
        time_stamp: dayjs.utc().format(),
        use_chat_history_from_db: true,
        use_prerouter_prompt: true,
        select_preset_id: `${id}`,
        snapchat_account_id: userMainInfo.mutable_username,
        last_request_cancelled: avoidedLastCall
    }

    const apiCall = async () => await API.requestAIAgent(params)
    try {
        const response = await Utils.callApiWithRetries(apiCall)
        return response // Return the successful response
    } catch (error) {
        console.error(error.message)
        // Handle error accordingly
        return { status: false }
    }
}

const processAIResponse = async data => {
    const forceSendSnapTrigger =
        data.action && data.action.force_send_snap ? data.action.force_send_snap.status : false

    const forceSendSnapUrl = forceSendSnapTrigger ? data.action.force_send_snap.url : null

    if (data.action_event) {
        if (data.action && data.action.force_chat_status === 'completed') {
            chrome.runtime.sendMessage({
                action: ServiceMessageName.ChatOverLay,
                params: {
                    uuid: currentOpenChatUser.uuid,
                    state: 'Complete'
                } as messageParamsType['data']
            })
            setCacheDisableChatUser(data.uid, {
                disabled: true,
                is_chat_disabled: true,
                ghost_message_count: 0,
                number_of_exchange: 0,
                phase: null
            })
            await closeCurrentChat()
            return
        }
        if (data.action_event == RespondAction.PostVerify) {
            chrome.runtime.sendMessage({
                action: ServiceMessageName.ChatOverLay,
                params: {
                    uuid: currentOpenChatUser.uuid,
                    state: 'Ghosting'
                } as messageParamsType['data']
            })
            await closeCurrentChat()
            return
        }
        if (data.action_event == RespondAction.DisableChat) {
            chrome.runtime.sendMessage({
                action: ServiceMessageName.ChatOverLay,
                params: {
                    uuid: currentOpenChatUser.uuid,
                    state: 'Converted'
                } as messageParamsType['data']
            })
            setCacheDisableChatUser(data.uid, {
                disabled: true,
                is_chat_disabled: true,
                ghost_message_count: 0,
                number_of_exchange: 0,
                phase: null
            })
            await closeCurrentChat()
            return
        }
    }

    chrome.runtime.sendMessage({
        action: ServiceMessageName.ChatOverLay,
        params: {
            uuid: currentOpenChatUser.uuid,
            state: 'Main Phase'
        } as messageParamsType['data']
    })

    await dispatchMessage(data.response, !!forceSendSnapUrl, forceSendSnapUrl)
}
