import { chatUserType } from '@/lib/types/scrape-engine.type'
import * as API from '@/scripts/api'
import { getUserInfoFromElement } from './getUserInfoFromElement'
import { processSendOpener } from './processSendOpener'
import * as Utils from '@/lib/common'
import {
    bBotRunningStatus,
    cacheDisableChatUser,
    cacheUsersOnHold,
    delayedChatUserDisplayName,
    failedLoadingSnap,
    isManualScroll,
    isUserListIterated,
    lastCacheCheckOpenerUserList,
    scrollFeed,
    setUserListIterated,
    updateLastCacheOpenerUserList,
    userMainInfo
} from '../..'
import { processNewChatMessage } from './processNewChatMessage'

// scroll from top to bottom checking opener and bottom to top checking new chats

export const feedUserDivClassName =
    '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'

export const processChatting = async () => {
    let userInfoArray: chatUserType[] = []

    const runProcessTopToBottom = async (userElements: NodeListOf<HTMLDivElement>) => {
        let newUserInfo: { element: HTMLDivElement; info: chatUserType }[] = []

        for (let i = 0; i < userElements.length; i++) {
            if (!bBotRunningStatus || isManualScroll) {
                return
            }
            const userInfo = getUserInfoFromElement(userElements[i])
            if (!userInfo) {
                continue
            }

            if (!userInfoArray.some(user => user.uuid === userInfo.uuid)) {
                userInfoArray.push(userInfo)
                if (
                    !userInfo.is_new_chat &&
                    !delayedChatUserDisplayName.includes(userInfo.userName) &&
                    !cacheDisableChatUser[userInfo.uuid]
                ) {
                    newUserInfo.push({ element: userElements[i], info: userInfo })
                }
            }
        }

        if (newUserInfo.length === 0) {
            return true
        } else {
            const newUserIds = newUserInfo.map(user => user.info.uuid)
            if (isUserListIterated) {
                const newUsers = newUserIds.filter(i => !lastCacheCheckOpenerUserList.includes(i))
                if (newUsers.length === 0) return true
            }

            const response = await API.checkOpener({
                request_user_id_list: newUserInfo.map(user => user.info.uuid),
                snapchat_account_id: userMainInfo.mutable_username
            })
            updateLastCacheOpenerUserList(newUserInfo.map(user => user.info.uuid))

            if (!response.data) return false

            if (isUserListIterated && response.data.length === 0) {
                return true
            }

            if (response.data && response.data.length > 0) {
                // There some user to send on opener to
                const uuidToSendOpener = response.data as string[]

                const userToSentOpenerTo = newUserInfo.filter((i, index) =>
                    uuidToSendOpener.includes(i.info.uuid)
                )

                if (userToSentOpenerTo && userToSentOpenerTo.length > 0) {
                    await processSendOpener(userToSentOpenerTo.map(i => i.element))
                }
            }

            return false
        }
    }

    const processWhileScrollToBottom = async () => {
        let totalCount = 0

        let usersElement = document.querySelectorAll(
            feedUserDivClassName
        ) as NodeListOf<HTMLDivElement>

        const hasNoNewOpener = await runProcessTopToBottom(usersElement)

        while ((usersElement[usersElement.length - 1] as HTMLElement).offsetParent !== null) {
            if (!bBotRunningStatus || isManualScroll) {
                return
            }
            totalCount = userInfoArray.length
            usersElement = document.querySelectorAll(feedUserDivClassName)
            const newChatUser = eligibleNewChatsUser(usersElement)

            if (newChatUser.length > 0) {
                await processNewChatMessage(newChatUser)
            }

            if (isUserListIterated) {
                if (hasNoNewOpener && newChatUser.length === 0) {
                    break
                }
                if (usersElement.length > 0) {
                    usersElement[usersElement.length - 1].scrollIntoView()
                }
            } else {
                scrollFeed(false)
            }

            await Utils.sleep(1000)
            const isMainLoadUnload = await Utils.waitForElementUnloadWithTimeout(
                'div[role="listitem"] div.maLbV',
                30000
            )
            if (!isMainLoadUnload) {
                window.location.reload()
                return
            }

            usersElement = document.querySelectorAll(feedUserDivClassName)

            const should_break = await runProcessTopToBottom(usersElement)

            const newChatUserInNextUsers = eligibleNewChatsUser(usersElement)

            if (should_break && !newChatUserInNextUsers) {
                break
            }

            // Loop it through till not increase the friends
            if (totalCount == userInfoArray.length) {
                break
            }
            console.log(`Total friends now: ${userInfoArray.length}`)
        }
    }

    await processWhileScrollToBottom()

    userInfoArray = []

    const runProcessGoingUp = async (userElements: NodeListOf<HTMLDivElement>) => {
        let newChatUserInfo: { element: HTMLDivElement; info: chatUserType }[] = []

        for (let i = 0; i < userElements.length; i++) {
            if (!bBotRunningStatus || isManualScroll) {
                return
            }
            const userInfo = getUserInfoFromElement(userElements[i])
            if (!userInfo) {
                continue
            }

            if (!userInfoArray.some(user => user.uuid === userInfo.uuid)) {
                userInfoArray.push(userInfo)
                const onHoldUser = Object.keys(cacheUsersOnHold)
                if (
                    (userInfo.is_new_chat || userInfo.is_new_snap) &&
                    !onHoldUser.includes(userInfo.uuid) &&
                    !cacheDisableChatUser[userInfo.uuid]
                ) {
                    if (
                        userInfo.is_new_snap &&
                        !userInfo.is_new_chat &&
                        failedLoadingSnap.includes(userInfo.uuid)
                    ) {
                        continue
                    }
                    newChatUserInfo.push({ element: userElements[i], info: userInfo })
                }
            }
        }

        if (newChatUserInfo && newChatUserInfo.length > 0) {
            await processNewChatMessage(newChatUserInfo.map(i => i.element))
        }
        return false
    }

    const processWhileScrollToTop = async () => {
        let totalCount = 0
        let usersElement = document.querySelectorAll(
            feedUserDivClassName
        ) as NodeListOf<HTMLDivElement>
        await runProcessGoingUp(usersElement)
        while (true) {
            if (!bBotRunningStatus || isManualScroll) {
                return
            }
            totalCount = userInfoArray.length

            if (usersElement.length > 0) {
                usersElement[0].scrollIntoView()
            }
            await Utils.sleep(1000)
            usersElement = document.querySelectorAll(feedUserDivClassName)
            await runProcessGoingUp(usersElement)

            // Loop it through till not increase the friends
            if (totalCount == userInfoArray.length) {
                break
            }
            console.log(`Total friends now: ${userInfoArray.length}`)
        }
    }

    await processWhileScrollToTop()
    if (isManualScroll) return
    setUserListIterated(true)
}

const eligibleNewChatsUser = (userElements: NodeListOf<HTMLDivElement>) => {
    const newUsers = []
    const onHoldUser = Object.keys(cacheUsersOnHold)
    for (let i = 0; i < userElements.length; i++) {
        const userInfo = getUserInfoFromElement(userElements[i])
        if (
            userInfo &&
            (userInfo.is_new_chat || userInfo.is_new_snap) &&
            !onHoldUser.includes(userInfo.uuid) &&
            !Object.keys(cacheDisableChatUser).includes(userInfo.uuid)
        ) {
            if (
                userInfo.is_new_snap &&
                !userInfo.is_new_chat &&
                failedLoadingSnap.includes(userInfo.uuid)
            ) {
                continue
            }
            newUsers.push(userElements[i])
        }
    }
    return newUsers
}
