import { ERROR_MSG } from '@/lib/constants'
import { ApiResponse } from './types/response.type'
import { LocalStorage } from '@/lib/chrome-storage'

const getLoggedInUser = async (): Promise<ApiResponse> => {
    try {
        const authHeaders1 = await LocalStorage.getItem('FRIENDS_AUTH_HEADERS')
        const headers1 = {}
        authHeaders1.map(_ => {
            headers1[_.name] = _.value
        })

        const friendFormData = await LocalStorage.getItem('FRIENDS_FORMDATA')

        let formData1 = {}

        formData1['user_ids'] = JSON.stringify(friendFormData['snapchat_user_id'])

        const response = await fetch(`https://web.snapchat.com/loq/snapchatter_public_info`, {
            method: 'POST',
            headers: headers1,
            body: `user_ids=${formData1['user_ids']}&source=CHAT`
        })
        if (response.ok) {
            const resData = await response.json()
            return {
                status: true,
                data: resData
            }
        } else {
            throw new Error('Error getting user detail')
        }
    } catch (error) {
        return {
            status: false,
            message: error?.message || ERROR_MSG.SOMETHING_WENT_WRONG
        }
    }
}

export default getLoggedInUser
