import { PresetSnapsAddType } from '@/lib/types/preset.type'
import * as Utils from '@/lib/common'
import { LocalStorage } from '@/lib/chrome-storage'
import { KEY_SB_TIMERS_SET } from '@/lib/constants'
import { addRequestUserType, SBTimerSetType } from '@/lib/types/scrape-engine.type'
import { bBotRunningStatus, ownerDetails, currentSBPreset as preset, userMainInfo } from '..'
import * as API from '@/scripts/api'
import dayjs from '@/lib/dayjs'
import { runCycleType } from '@/lib/types/user.type'

export const listClass = '.LtQF8 .zYgGl .JB8Z3 .ReactVirtualized__Grid__innerScrollContainer[role="list"]'
var disabledAdds = []
let todaysLimitLeft = 1000000000

function isTimeInRange(timeRanges: runCycleType[]) {
    // Convert the input dateTime to a dayjs object

    const utcNow = dayjs.utc()

    for (let range of timeRanges) {
        // Convert start_time and end_time to dayjs objects
        const startTime = dayjs(range.start_time, 'HH:mm').utc()
        const endTime = dayjs(range.end_time, 'HH:mm').utc()

        // Check if inputTime falls within the range
        if (utcNow.isBetween(startTime, endTime, null, '[]')) {
            return true
        }
    }
    return false
}

export const checkSnapsAddCycleTimer = async () => {
    const { snapsAdd = {} } = preset.details ?? {}

    if (!snapsAdd?.enabledSnapAdd) return

    if (snapsAdd?.delayPerCycle) {
        const isEligible = checkForSnapAddEligibility(snapsAdd)
        if (!isEligible) return

        const dailyLimit = snapsAdd?.addLimit

        if (dailyLimit <= 0) return

        const { ranged, delayPerCycleRate, delayPerCycleMax, delayPerCycleMin } =
            snapsAdd?.delayPerCycle ?? {}

        const setNextAddCycleTimer = async () => {
            let delayOf = delayPerCycleRate

            if (ranged) {
                delayOf = Utils.getRandomNumberInRange(delayPerCycleMin, delayPerCycleMax)
            }

            const timer = Utils.getNextTimer(delayOf)

            let currentValue = await LocalStorage.getItem(KEY_SB_TIMERS_SET)

            await LocalStorage.setItem(KEY_SB_TIMERS_SET, {
                ...(currentValue ?? {}),
                add_cycle_timer: timer
            })
        }

        const sb_timers: SBTimerSetType = await LocalStorage.getItem(KEY_SB_TIMERS_SET)

        // snaps add trigger
        if (sb_timers && sb_timers.add_cycle_timer) {
            const canCallNextCycle = Utils.isTimePassed(sb_timers.add_cycle_timer)

            if (canCallNextCycle && ownerDetails.owner_setting?.runCycle?.enabled) {
                const isInRunTime = isTimeInRange(ownerDetails.owner_setting?.runCycle?.schedule)
                if (!isInRunTime) return
            }

            if (canCallNextCycle) {
                await setNextAddCycleTimer()
                if (dailyLimit > 0) {
                    const res = await API.getTodaysAddCount(userMainInfo.mutable_username)

                    if ('data' in res) {        
                        if (res.data <= dailyLimit) {
                            todaysLimitLeft = dailyLimit - res.data
                        }
                    }

                    if (todaysLimitLeft <= 0) {
                        return
                    }
                }

                try {
                    const getOwnerProfileCall = async () =>
                        await API.getOwnerProfile(userMainInfo.mutable_username)
                    const response = await Utils.callApiWithRetries(getOwnerProfileCall)
                    disabledAdds = response.data.disabled_adds ?? []
                } catch (error) {
                    console.error('Error while fetching owner details', error.message)
                }

                await processAddSnaps()
            }
        } else {
            await setNextAddCycleTimer()
        }
    }
}

const processAddSnaps = async () => {
    const addRequestUsersList: addRequestUserType[] = []

    try {
        const buttonClass = '.kwuI_.eKaL7.Bnaur.zUzvu'
        const buttonElements = (await Utils.waitForElement(
            buttonClass,
            'snap_add'
        )) as HTMLButtonElement

        if (buttonElements) {
            buttonElements.click()
        }

        const popup = (await Utils.waitForElement(listClass, 'snap_add_list')) as HTMLDivElement

        const viewMore = popup.querySelector('div.g8CcQ') as HTMLDivElement

        if (viewMore) {
            viewMore.click()
        }
        await Utils.sleep(500)
        await getAddRequestUserList(popup, addRequestUsersList)

        const { snapsAdd } = preset.details ?? {}
        const { ranged, addAcceptedCycleMax, addAcceptedCycleMin, addAcceptedCycleRate } =
            snapsAdd?.addAcceptedCycle ?? {}

        const randomizeUser = ranged
            ? getRandomUsernames(
                  addRequestUsersList,
                  Utils.getRandomNumberInRange(addAcceptedCycleMin, addAcceptedCycleMax)
              )
            : getRandomUsernames(addRequestUsersList, addAcceptedCycleRate)

        await goesUpAddingSnaps(
            popup,
            todaysLimitLeft < randomizeUser.length
                ? randomizeUser.slice(0, todaysLimitLeft)
                : randomizeUser
        )
    } catch (error) {
        console.log(error)
    } finally {
        const closeButtonClass = '.kwuI_.tnGOU.eKaL7.Bnaur.zUzvu'
        const closeButtonElements = document.querySelector(closeButtonClass) as HTMLButtonElement
        if (closeButtonElements) {
            closeButtonElements.click()
        }
        window.location.reload()
    }
}

const scrollAddFriends = async (toTop: boolean) => {
    const popup = document.querySelector(listClass) as HTMLDivElement
    if (popup) {
        if (toTop) {
            popup?.scrollTo(0, 0)
        } else {
            popup?.scrollTo(0, popup?.scrollHeight + 100 || 10000000)
        }
    }
}

const getAddRequestUserList = async (popup: HTMLDivElement, userList: addRequestUserType[]) => {
    const runProcess = async divElements => {
        let divElementToSendOpenner = []
        let newUserInfo = []
        for (let i = 0; i < divElements.length; i++) {
            if (!bBotRunningStatus) {
                return
            }
            const userInfo = getAddRequestUserInfo(divElements[i])
            if (!userInfo) {
                continue
            }
            if (!userList.some(user => user.username === userInfo.username)) {
                userList.push(userInfo)
                divElementToSendOpenner.push(divElements[i])
                newUserInfo.push(userInfo)
            }
        }

        if (newUserInfo.length == 0) {
            return true
        }
    }

    const processWhileScrollToBottom = async () => {
        let totalCount = 0
        let usersDivList = popup.querySelectorAll('div.H8CAi')
        await runProcess(usersDivList)
        while (true) {
            if (!bBotRunningStatus) {
                return
            }
            totalCount = userList.length

            usersDivList[usersDivList.length - 1].scrollIntoView()

            await Utils.sleep(1000)
            usersDivList = popup.querySelectorAll('div.H8CAi')

            const should_break = await runProcess(usersDivList)

            if (should_break) {
                break
            }

            // Loop it throuth seems not increase the friends
            if (totalCount == usersDivList.length) {
                break
            }
            console.log(`Total friends now: ${userList.length}`)
        }

        console.log('User Info Array:', userList)
    }

    await processWhileScrollToBottom()
    scrollAddFriends(true)
}

function getRandomUsernames(users: addRequestUserType[], count: number): string[] {
    const { snapsAdd = {} } = preset.details ?? {}
    const { declineQuickAdds = false } = snapsAdd

    const shuffledUsers = users
        .filter(i => (declineQuickAdds ? !i.quickAdd : true))
        .filter(i => !disabledAdds.includes(i.username))

    for (let i = shuffledUsers.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[shuffledUsers[i], shuffledUsers[j]] = [shuffledUsers[j], shuffledUsers[i]]
    }
    const randomUsernames = shuffledUsers.slice(0, count).map(user => user.username)

    return randomUsernames
}

export const getAddRequestUserInfo = (user: HTMLDivElement): addRequestUserType | null => {
    const userNameDiv = user.querySelector('.NKUoR .RMaXm .iQDcn.nonIntl')
    const userDisplayDiv = user.querySelector('.NKUoR .RMaXm .YifBM.nonIntl')
    const acceptButton = user.querySelector('.sGsBQ .F7jpS.eKaL7.Bnaur.zUzvu') as HTMLButtonElement
    const addStatus = user.querySelector('.tg1Lo') as HTMLDivElement
    
    return userNameDiv
        ? {
              username: userNameDiv.textContent,
              acceptButton,
              displayName: userDisplayDiv.textContent,
              quickAdd: addStatus?.innerText?.toLowerCase().replace(/\s/g, '').includes('quickadd')
                  ? true
                  : false
          }
        : null
}

// value is set correctly or not
const checkForSnapAddEligibility = (snapsAdd: PresetSnapsAddType) => {
    const { ranged, delayPerCycleRate, delayPerCycleMax, delayPerCycleMin } =
        snapsAdd?.delayPerCycle ?? {}

    const {
        ranged: addAcceptRange,
        addAcceptedCycleMax,
        addAcceptedCycleMin,
        addAcceptedCycleRate
    } = snapsAdd?.addAcceptedCycle ?? {}

    // returns if value not set properly
    if (ranged) {
        if (!delayPerCycleMax || !delayPerCycleMin) return false
    } else {
        if (!delayPerCycleRate) return false
    }

    // check for number of snap add set
    if (addAcceptRange) {
        if (!addAcceptedCycleMax || !addAcceptedCycleMin) return false
    } else {
        if (!addAcceptedCycleRate) return false
    }
    return true
}

const goesUpAddingSnaps = async (popup: HTMLDivElement, usersUsername: string[]) => {
    const visitedUsers: string[] = []

    let addedUsers = 0

    const runProcess = async divElements => {
        let divElementToAcceptRequest = []
        let newUserInfo = []
        for (let i = 0; i < divElements.length; i++) {
            if (!bBotRunningStatus) {
                return
            }
            const userInfo = getAddRequestUserInfo(divElements[i])
            if (!userInfo) {
                continue
            }
            if (!visitedUsers.includes(userInfo.username)) {
                visitedUsers.push(userInfo.username)
                divElementToAcceptRequest.push(divElements[i])
                newUserInfo.push(userInfo)
            }
        }

        if (newUserInfo.length == 0) {
            return true
        } else {
            const shuffledArray = Utils.shuffleArray(divElementToAcceptRequest)

            for (let elem of shuffledArray) {
                try {
                    if (!bBotRunningStatus) {
                        return
                    }
                    const userInfo = getAddRequestUserInfo(elem)

                    if (usersUsername.includes(userInfo.username) && userInfo.acceptButton) {
                        const popup = document.querySelector(listClass)
                        if (!popup) continue
                        userInfo.acceptButton.click()

                        if (ownerDetails.owner_setting?.delayChatting.enabled) {
                            const sb_timers: SBTimerSetType =
                                await LocalStorage.getItem(KEY_SB_TIMERS_SET)

                            await LocalStorage.setItem(KEY_SB_TIMERS_SET, {
                                ...(sb_timers ?? {}),
                                delayed_users: {
                                    ...(sb_timers?.delayed_users ?? {}),
                                    [userInfo.displayName]: Utils.getNextTimer(
                                        ownerDetails.owner_setting?.delayChatting.delay
                                    )
                                }
                            })
                        }

                        addedUsers++
                        await Utils.sleep(1000)
                    }
                } catch (error) {
                    console.log(error)
                }
            }
            divElements[0].scrollIntoView()
        }
    }

    const processWhileScrollToTop = async () => {
        let totalCount = 0
        let usersDivList = popup.querySelectorAll('div.H8CAi')
        await runProcess(usersDivList)
        while (true) {
            if (!bBotRunningStatus) {
                return
            }
            totalCount = visitedUsers.length

            await Utils.sleep(1000)
            usersDivList = popup.querySelectorAll('div.H8CAi')

            const should_break = await runProcess(usersDivList)

            if (should_break) {
                break
            }
            // Loop it through seems not increase the friends
            if (totalCount == visitedUsers.length) {
                break
            }
        }
    }
    await processWhileScrollToTop()
    if (addedUsers) {
        await API.updateTodaysAddCounter({
            increment_value: addedUsers,
            owner_id: userMainInfo.mutable_username
        })
    }
}
