import * as API from '@/scripts/api'
import { makeAutoObservable } from 'mobx'
import {
    KEY_SB_CURRENT_MODEL_ID,
    KEY_SB_CURRENT_PRESET_ID,
    KEY_SB_LICENSE_KEY
} from '@/lib/constants'
import { LocalStorage } from '@/lib/chrome-storage'

class AuthStore {
    licenseInformation = null
    license_key = null
    init_loading = true

    constructor() {
        makeAutoObservable(this)
        this.init()
    }

    async validateLicenseKey(license_key: string) {
        console.log('Validating license key...')
        if (!license_key || !license_key?.trim()) {
            await this.signOut()
            return false
        }
        let response
        for (let i = 0; i < 3; i++) {
            response = await API.getClientInfo(license_key)
            if (response.status) {
                const data = response.data
                if (data && data.user && data.user.license_key) {
                    console.log('License key validated successfully.')
                    await this.signIn(data.user.license_key, data.user)
                    console.log('Valid license key, Sign in successfully')
                    return true
                }
            } else if (response.message === 'Invalid user') {
                await this.signOut()
                return false
            }
        }

        console.log('License key validation failed: ', response.message)
        await this.signOut()
        console.log('Invalid license key')
        return false
    }

    async init() {
        console.log('Initializing AuthStore...')
        this.init_loading = true
        this.license_key = null
        this.licenseInformation = null
        const license_key = await LocalStorage.getItem(KEY_SB_LICENSE_KEY)

        console.log('Retrieved license key from local storage: ', license_key)
        await this.validateLicenseKey(license_key)

        console.log('AuthStore initialization complete.')
        this.init_loading = false
    }

    async clearOutLocalStorage() {
        await LocalStorage.removeItems([
            KEY_SB_LICENSE_KEY,
            KEY_SB_CURRENT_PRESET_ID,
            KEY_SB_CURRENT_MODEL_ID
        ])
    }

    async signOut() {
        this.setLicenseKey(null)
        this.licenseInformation = null
        await this.clearOutLocalStorage()
    }

    async signIn(license_key: string, user: any) {
        this.setLicenseKey(license_key)
        this.licenseInformation = user
        await LocalStorage.setItem(KEY_SB_LICENSE_KEY, license_key)
    }

    setLicenseKey(license_key) {
        this.license_key = license_key
    }

    getAPIKey() {
        return this.license_key
    }

    get isAuthenticated() {
        return !!this.license_key && !!this.licenseInformation
    }

    // We will show starter guide only when user has complete preset information
    get show_starter_guide() {
        return (
            (this.licenseInformation ? !this.licenseInformation.pass_starter : true) &&
            !this.init_loading
        )
    }

    get API_KEY() {
        return this.license_key
    }
}

export default AuthStore
