import { LocalStorage } from '@/lib/chrome-storage'
import * as Utils from '@/lib/common'
import { isTimePassed } from '@/lib/common'
import { SB_LAST_CHECK_OLD_CHAT, X_HOURS_FOLLOW_UP_DEFAULT_MESSAGE } from '@/lib/constants'
import { chatUserType } from '@/lib/types/scrape-engine.type'
import * as API from '@/scripts/api'
import {
    bBotRunningStatus,
    cacheDisableChatUser,
    currentChatConversationStatus,
    currentOpenChatUser,
    currentSBPreset,
    isManualScroll,
    scrollFeed,
    setCurrentChatUser,
    userMainInfo
} from '../../..'
import { checkChatConversationStatus } from '../checkDisableChat'
import { dispatchMessage } from '../dispatchMessage'
import { checkUserPresentInCurrentFeed, getUserInfoFromElement } from '../getUserInfoFromElement'
import { scrapeChatHistory } from '../scrapeChatHistory'
import { closeCurrentChat } from '../../closeCurrentChat'

const feedUserDivClassName =
    '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'

export const processOldChatMessage = async (userElements: HTMLDivElement[]) => {
    for (let userElement of userElements) {
        if (!bBotRunningStatus) {
            return
        }
        const userInfo = getUserInfoFromElement(userElement)

        if (userInfo) {
            await checkChatConversationStatus(userInfo.uuid, userInfo.userName)

            if (
                cacheDisableChatUser[userInfo.uuid] ||
                currentChatConversationStatus.final_static_message_is_sent
            ) {
                continue
            }
            setCurrentChatUser(userInfo)

            const isUserPresentInFeed = checkUserPresentInCurrentFeed()
            if (!isUserPresentInFeed) {
                continue
            }

            const statusElm: HTMLSpanElement = isUserPresentInFeed.querySelector('.GQKvA .nonIntl')

            let message = ''

            const { details } = currentSBPreset
            const { followUps } = details

            const { xHourFollowUp } = followUps

            if (xHourFollowUp.defaultSetting) {
                message =
                    X_HOURS_FOLLOW_UP_DEFAULT_MESSAGE[
                        Utils.getBelowRandomNumber(X_HOURS_FOLLOW_UP_DEFAULT_MESSAGE.length)
                    ]
            } else {
                message =
                    xHourFollowUp.messages[
                        Utils.getBelowRandomNumber(xHourFollowUp.messages.length)
                    ].message
            }

            statusElm.click()
            await scrapeChatHistory()
            await dispatchMessage(message)
            await API.syncCustomBotMessage({
                snapchat_account_id: userMainInfo.mutable_username,
                request_user_id: userInfo.uuid,
                bot_message: message,
                select_preset_id: `${currentSBPreset.id}`,
                follow_up_message: true
            })
            await closeCurrentChat()
        }
    }
}

export const processOldChat = async () => {
    const getUnloadChatUser = await LocalStorage.getItem(SB_LAST_CHECK_OLD_CHAT)

    if (!getUnloadChatUser || isTimePassed(getUnloadChatUser)) {
        await LocalStorage.setItem(SB_LAST_CHECK_OLD_CHAT, Utils.getNextTimer(30))

        let userInfoArray = []
        let userToMsg = await msgOlderUsers()
        if (userToMsg.length === 0) return

        const runProcessToCheckUserInList = async (userElements: NodeListOf<HTMLDivElement>) => {
            let newUserElementSendStaticMsg: { element: HTMLDivElement; info: chatUserType }[] = []

            for (let i = 0; i < userElements.length; i++) {
                if (!bBotRunningStatus || isManualScroll) {
                    return
                }
                const userInfo = getUserInfoFromElement(userElements[i])
                if (!userInfo) {
                    continue
                }

                if (!userInfoArray.some(user => user.uuid === userInfo.uuid)) {
                    userInfoArray.push(userInfo)
                    if (userToMsg.includes(userInfo.uuid)) {
                        userToMsg = userToMsg.filter(userId => userId !== userInfo.uuid)

                        newUserElementSendStaticMsg.push({
                            element: userElements[i],
                            info: userInfo
                        })
                    }
                }
            }

            if (newUserElementSendStaticMsg.length > 0) {
                await processOldChatMessage(newUserElementSendStaticMsg.map(i => i.element))
            }
        }

        const processWhileScrollToBottom = async () => {
            let totalCount = 0
            let userElements = document.querySelectorAll(
                feedUserDivClassName
            ) as NodeListOf<HTMLDivElement>
            await runProcessToCheckUserInList(userElements)

            if (userToMsg.length === 0 || isManualScroll) {
                return
            }
            while (userToMsg.length > 0) {
                if (!bBotRunningStatus || isManualScroll) {
                    return
                }
                totalCount = userInfoArray.length
                userElements = document.querySelectorAll(feedUserDivClassName)

                scrollFeed(false)

                await Utils.sleep(1000)
                userElements = document.querySelectorAll(feedUserDivClassName)

                await runProcessToCheckUserInList(userElements)

                // Loop it through till not increase the friends
                if (totalCount == userInfoArray.length || userToMsg.length === 0) {
                    scrollFeed(true)
                    break
                }
            }
        }

        await processWhileScrollToBottom()
    }
}

const msgOlderUsers = async () => {
    const { details } = currentSBPreset
    const { followUps } = details

    const { xHourFollowUp } = followUps
    const oldConversations = await API.getOldConversations(
        userMainInfo.mutable_username,
        xHourFollowUp.defaultSetting ? 12 : xHourFollowUp.hours
    )

    if (oldConversations.status) {
        return oldConversations.data
    }

    return []
}
