import { checkUserPresentInCurrentFeed, getUserInfoFromElement } from './getUserInfoFromElement'
import * as Utils from '@/lib/common'
import * as API from '@/scripts/api'
import { scrapeChatHistory } from './scrapeChatHistory'
import { chatUserType, threadMessageType } from '@/lib/types/scrape-engine.type'
import {
    bBotRunningStatus,
    cacheDisableChatUser,
    currentOpenChatUser,
    currentSBPreset,
    delayedChatUserDisplayName,
    filterOutfitSnaps,
    setCurrentChatUser,
    userMainInfo
} from '../..'
import { OUTFIT_TYPE, PresetOpenerType } from '@/lib/types/preset.type'
import { PurposeType, SBSnapSourceType, ServiceMessageName } from '@/lib/constants'
import { getSpecificSnapsUrl, getUnusedSnap } from './liveSnaps'
import { dispatchMessage } from './dispatchMessage'
import { closeCurrentChat } from '../closeCurrentChat'
import { checkChatConversationStatus } from './checkDisableChat'
import { messageParamsType } from '@/lib/types/chatting-overlay.type'

export const processSendOpener = async (userElements: HTMLDivElement[]) => {
    for (let userElement of userElements) {
        if (!bBotRunningStatus) {
            return
        }
        const userInfo = getUserInfoFromElement(userElement)

        if (userInfo && !userInfo.is_new_chat) {
            if (delayedChatUserDisplayName.includes(userInfo.userName)) return
            await checkChatConversationStatus(userInfo.uuid, userInfo.userName)

            if (cacheDisableChatUser[userInfo.uuid]) {
                continue
            }
            setCurrentChatUser(userInfo)

            const isUserPresentInFeed = checkUserPresentInCurrentFeed()
            if(!isUserPresentInFeed) {
                continue
            }

            const statusElm: HTMLSpanElement = isUserPresentInFeed.querySelector('.GQKvA .nonIntl')

            statusElm.click()

            const chatMessage = await scrapeChatHistory()

            if (chatMessage.length === 0) {
                await sendOpenerMessage(userInfo)
            } else {
                const chat_history = transformMessages(chatMessage)

                await API.syncUserConversation({
                    bitmoji_avatar_id_list: [userInfo.bitmoji_avatar_id],
                    chat_history_list: [chat_history],
                    request_user_id_list: [userInfo.uuid],
                    request_username_list: [userInfo.userName],
                    snapchat_account_id: userMainInfo.mutable_username,
                    select_preset_id: `${currentSBPreset.id}`
                })
            }

            chrome.runtime.sendMessage({
                action: ServiceMessageName.ChatOverLay,
                params: { uuid: userInfo.uuid, state: 'Main Phase' } as messageParamsType['data']
            })
            await closeCurrentChat()
        }
    }
}

const transformMessages = (messages: threadMessageType[]) => {
    let transformed: { user_message: string; ai_response: string }[] = []
    let currentUserMessage = null
    let currentAiResponse = null

    messages.forEach((msg, index) => {
        if (msg?.role !== 'Me') {
            if (currentUserMessage) {
                transformed.push({
                    user_message: currentUserMessage,
                    ai_response: currentAiResponse
                })
                currentAiResponse = null
            }
            currentUserMessage = msg.text
        } else if (msg?.role === 'Me') {
            if (currentAiResponse) {
                currentAiResponse += ' | ' + msg.text
            } else {
                currentAiResponse = msg.text
            }
        }

        // Handle the last message
        if (index === messages.length - 1) {
            transformed.push({
                user_message: currentUserMessage,
                ai_response: currentAiResponse
            })
        }
    })

    return transformed
}

const getOptionToSendOpener = async () => {
    let message = ''
    let performSendSnap = false
    let snapUrl = null

    if (currentSBPreset) {
        const { opener = {} as PresetOpenerType, snaps } = currentSBPreset.details

        if (opener === undefined) {
            return { message, performSendSnap, snapUrl }
        }
        const randomOpeningText = ['Hii', 'Heyy', 'Hii :)', 'Heyy :)']

        if (opener.bUseAIOpener || opener.bDefaultSettings) {
            message = randomOpeningText[Utils.getBelowRandomNumber(randomOpeningText.length)]
        } else if (opener.message?.trim() !== '') {
            message = opener.message
        }

        let snapUrlsId = []

        if (
            (opener.snapPoolType === SBSnapSourceType.MAIN_MEDIA_POOL.value ||
                opener.bDefaultSettings) &&
            snaps &&
            snaps.length > 0
        ) {
            let mainPoolOpenerSnap = snaps.filter(
                i => i.purpose === PurposeType.MAIN && i.outfit === OUTFIT_TYPE.OUTFIT_1
            )
            if (mainPoolOpenerSnap.length === 0) {
                mainPoolOpenerSnap = snaps.filter(i => i.purpose === PurposeType.MAIN && !i.outfit)
            }

            snapUrlsId = mainPoolOpenerSnap.map(i => i.snapUrl)
        } else if (
            opener.snapPoolType === SBSnapSourceType.SPECIFIC_MEDIA_POOL.value &&
            opener.specificSnapIds
        ) {
            const specificSnapIds = opener.specificSnapIds
            if (specificSnapIds && specificSnapIds.length > 0) {
                snapUrlsId = getSpecificSnapsUrl(specificSnapIds, 1)
            }
        }
        if (snapUrlsId.length > 0) {
            const filteredSnapUrl = await getUnusedSnap(snapUrlsId)
            if (filteredSnapUrl) {
                snapUrl = filteredSnapUrl
                performSendSnap = true
            }
        }
    }

    return { message, performSendSnap, snapUrl }
}

const sendOpenerMessage = async (userInfo: chatUserType) => {
    const { message, performSendSnap, snapUrl } = await getOptionToSendOpener()

    const { snaps } = currentSBPreset.details

    const snap = snaps.find(i => i.snapUrl === snapUrl)

    const sent_pass = await dispatchMessage(message, performSendSnap, snapUrl)
    if (sent_pass) {
        await API.flagOpener({
            request_user_id_list: [userInfo.uuid],
            request_username_list: [userInfo.userName],
            bitmoji_avatar_id_list: [userInfo.bitmoji_avatar_id],
            openner_message: message,
            snapchat_account_id: userMainInfo.mutable_username,
            send_snap_id: snap?.id,
            select_preset_id: `${currentSBPreset.id}`,
            snap_sent_id: snap?.id
        })
    }
}
