import { PresetCtaInfoType } from '@/lib/types/preset.type'
import { currentSBPreset } from '../..'
import * as Utils from '@/lib/common'

export const getRandomCTA = async () => {
    const { details = {}, id } = currentSBPreset
    const { cta } = details
    let derivedCtaInfo: PresetCtaInfoType = null
    const { ctaSet } = cta
    const { activeCta, ctaInfo, sendRandomCta } = ctaSet

    if (sendRandomCta) {
        const randomIndex = Utils.getBelowRandomNumber(ctaInfo.length)
        derivedCtaInfo = ctaInfo[randomIndex]
    } else {
        derivedCtaInfo = ctaInfo[activeCta ?? 0]
    }

    return derivedCtaInfo
}

