export const checkNoLongerViewingLoaded = () => {
    const noLongerViewingContent = document.querySelector(
        '.Vbjsg.WJjwl ._XMCw .S4e9r .ecBYF .ejVI4 .RZoOk'
    ) as HTMLDivElement

    return !!noLongerViewingContent?.innerText
        .replace(/\s/g, '')
        .toLowerCase()
        .includes('youarenolongerviewing')
}
