import { UserInfoType } from '@/lib/types/user.type'
import * as API from '@/scripts/api'
import { addFriendsParamsType } from '@/scripts/api/types/params.type'

export const saveFriendsList = async (userMainInfo: UserInfoType) => {
    const friends = await API.getUserFriends()

    if (friends.status) {
        const parsedFriends: addFriendsParamsType['friends_list'] = friends.data.friends
            .filter(
                i =>
                    !['teamsnapchat', 'myai', userMainInfo.mutable_username].includes(
                        i.mutable_username
                    )
            )
            .map(j => ({
                username: j.mutable_username,
                display_name: j.display,
                bitmoji_avatar_id: j.bitmoji_avatar_id ?? null
            }))

        if (parsedFriends.length > 0) {
            const res = await API.addFriends({
                friends_list: parsedFriends,
                snapchat_account_id: userMainInfo.mutable_username
            })
            if (!res.status) {
                console.error(`Error while saving friends list : ${res?.message}`)
            }
        }
    } else {
        console.error(`Error getting friends list : ${friends?.message}`)
    }
}
