import { chatUserType } from '@/lib/types/scrape-engine.type'
import { currentOpenChatUser } from '../..'

export const getUserInfoFromElement: (element: HTMLDivElement) => chatUserType | null = (
    userElement: HTMLDivElement
) => {
    try {
        // get uuid
        const userDisplayNameElement: HTMLDivElement = userElement.querySelector('.mYSR9.nonIntl')
        const uniqueUserId = userDisplayNameElement.getAttribute('id')
        const uuid = uniqueUserId.substring('title-'.length)

        // get user display name
        const displayNameInnerElements: NodeListOf<HTMLSpanElement> =
            userElement.querySelectorAll('.FiLwP .nonIntl')
        // groupname will have displayNameInnerElements length 0 or more than 1
        if (displayNameInnerElements.length !== 1) {
            throw new Error('Chat is a group chat')
        }
        const userName = displayNameInnerElements[0]?.innerText

        // get user chat status
        const chatStatusElement: HTMLSpanElement = userElement.querySelector('.GQKvA .nonIntl')
        const status = chatStatusElement?.innerText

        // verify valid user
        const isUserValid =
            status && userName !== 'My AI' && userName !== 'Team Snapchat' && !!userName
        if (!isUserValid) {
            throw new Error('Not a valid user')
        }

        // get user unique emoji id
        const emoji = userElement.querySelector('.lzKDW .Dozhe') as HTMLImageElement
        let bitmoji_avatar_id = null
        if (emoji) {
            const imageSrc = emoji.src
            const regex = /panel\/\d+-(\d+_\d+-s5)/
            const match = imageSrc.match(regex)

            if (match) {
                bitmoji_avatar_id = match[1]
            }
        }

        // check if chat has new message
        const is_new_chat = status
            ? status.toLowerCase().replace(/\s/g, '').includes('newchat')
            : false

        const hasViewButton = userElement.querySelector('.w15C2') as HTMLDivElement

        // only considering viewable snap chats
        const is_new_snap = hasViewButton
            ? hasViewButton.innerText.toLowerCase().replace(/\s/g, '').includes('view')
            : false
        return {
            uuid,
            userName,
            status,
            isUserValid,
            is_new_chat,
            bitmoji_avatar_id,
            is_new_snap
        }
    } catch (error) {
        return null
    }
}

const feedUserDivClassName =
    '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'

export const checkUserPresentInCurrentFeed = () => {
    let userElements = document.querySelectorAll(feedUserDivClassName) as NodeListOf<HTMLDivElement>

    for (let i = 0; i < userElements.length; i++) {
        const userInfo = getUserInfoFromElement(userElements[i])
        if (userInfo && userInfo.uuid === currentOpenChatUser.uuid) {
            return userElements[i]
        }
    }

    console.log("@@@@ userElements", userElements)
    return null
}
