// constant for class name
const feedClass = 'div.ReactVirtualized__Grid.ReactVirtualized__List.QAr02'
const feedUserListClass = '.ReactVirtualized__Grid__innerScrollContainer [role="listitem"] .O4POs'

const handleResetVariableOnBotStart = () => {
    lastCacheCheckOpenerUserList = []
    cacheDisableChatUser = {}
    cameraHadLoad = false
    scrollToTopTimer = null
    isManualScroll = false
}

chrome.runtime.onMessage.addListener(async function (message, sender, sendResponse) {
    const { action, data } = message

    if (action == ServiceMessageName.RunBot) {
        bBotRunningStatus = true
        handleResetVariableOnBotStart()
        botConfig = (await LocalStorage.getItem(KEY_SB_BOT_CONFIG)) as BotConfigType
        cameraHadLoad = (await LocalStorage.getItem(SB_CAMERA_LOADED)) as boolean
        const license = authStore.getAPIKey()

        if (!license) {
            await authStore.init()
        }

        currentSBPreset = botConfig.preset
        const res = await initialize()

        if (res) {
            const syncOwnerPresetCall = async () =>
                await API.syncOwnerPreset({
                    owner_id: userMainInfo.mutable_username,
                    preset_id: currentSBPreset.id
                })

            try {
                await Utils.callApiWithRetries(syncOwnerPresetCall)
            } catch (error) {
                console.error('Error syncing preset with ownerid', error.message)
            }

            const getOwnerProfileCall = async () =>
                await API.getOwnerProfile(userMainInfo.mutable_username)

            try {
                const response = await Utils.callApiWithRetries(getOwnerProfileCall)

                ownerDetails = response.data
                botCurrentDay = ownerDetails.first_activation_date
                    ? Math.abs(
                          dayjs(ownerDetails.first_activation_date).utc().diff(dayjs.utc(), 'days')
                      ) + 1
                    : 1
            } catch (error) {
                console.error('Error while fetching owner details', error.message)
            }

            const storiesRes = await API.getStories(currentSBPreset.id)
            if (storiesRes.status) {
                stories = storiesRes.data
            }

            await API.snapRefine(currentSBPreset.id)

            startProcess()
        }
    }
    if (action == ServiceMessageName.StopBot) {
        bBotRunningStatus = false
    }
    if (action == ServiceMessageName.UpdateBotConfig) {
        botConfig = (await LocalStorage.getItem(KEY_SB_BOT_CONFIG)) as BotConfigType
        currentSBPreset = botConfig.preset
    }
    if (action == ServiceMessageName.PauseChatting) {
        handlePauseChatting(data.ruid, data.pause)
    }
})

const selectOutFitSnap = (outfit: OUTFIT_TYPE, botCurrentChatDay) => {
    if (botCurrentChatDay === 1) {
        return outfit === OUTFIT_TYPE.OUTFIT_1 ? true : false
    } else if (botCurrentChatDay === 2) {
        return outfit === OUTFIT_TYPE.OUTFIT_2 ? true : false
    } else {
        return outfit === OUTFIT_TYPE.OUTFIT_3 ? true : false
    }
}

export const filterOutfitSnaps = (botChatDay = 1) => {
    const { snaps } = currentSBPreset.details

    if (snaps) {
        const snapForTheDay = snaps.filter(
            i => [PurposeType.STORY].includes(i.purpose) || selectOutFitSnap(i.outfit, botChatDay)
        )
        if (snapForTheDay.length > 0) {
            return snapForTheDay
        } else {
            return snaps.filter(i => [PurposeType.STORY].includes(i.purpose) || !i.outfit)
        }
    }
    return [] as LiveSnapType[]
}

export const scrollFeed = async (toTop: boolean) => {
    const feedDiv = document.querySelector(feedClass)
    if (feedDiv) {
        if (toTop) {
            feedDiv?.scrollTo(0, 0)
        } else {
            const divElements = document.querySelectorAll(feedUserListClass)
            divElements[divElements.length - 1].scrollIntoView()
        }
    }
}

export const updateLastCacheOpenerUserList = (userIds: string[]) => {
    lastCacheCheckOpenerUserList = userIds
}

export const updateFailedLoadingSnap = (chatId: string, add: boolean) => {
    if (add) {
        failedLoadingSnap = uniq([...failedLoadingSnap, chatId])
    } else {
        failedLoadingSnap = failedLoadingSnap.filter(i => i !== chatId)
    }
}

