export const updateStories = (data: Partial<StoryType>) => {
    const { id, ...rest } = data

    const index = stories.findIndex(i => i.id === id)

    stories[index] = { ...stories[index], ...rest }
}

const initialize = async () => {
    const res = await API.getLoggedInUser()

    if (res.status) {
        userMainInfo = res.data.snapchatters[0]
        return true
    } else {
        console.log(`Initialize Error : ${res?.message}`)
        setTimeout(() => {
            window.location.reload()
        }, 5000)
        return false
    }
}

const processMessages = async () => {
    try {
        await Utils.waitForElement(feedUserListClass, 'feed_section')
        console.log('!!!!!!! start processChatting')
        await processChatting()
        // x hours follow up
        console.log('!!!!!!! start processOldChat')
        await processOldChat()
    } catch (error) {
        console.log(error)
    }
}

const startProcess = async () => {
    await closeCurrentChat()

    const { details } = currentSBPreset
    const { enableChatting = false } = details
    const feedDiv = (await Utils.waitForElement(
        feedClass,
        'feed_section_on_Start',
        10000
    )) as HTMLDivElement

    const handleManualScroll = e => {
        if (scrollToTopTimer) clearTimeout(scrollToTopTimer)
        const newLastTimerId = setTimeout(() => {
            scrollFeed(true)
            isManualScroll = true
        }, 5000)

        scrollToTopTimer = newLastTimerId
    }

    feedDiv?.addEventListener('wheel', handleManualScroll)
    scrollFeed(true)

    await saveFriendsList(userMainInfo)

    const getUnloadChatUser = await LocalStorage.getItem(SB_UNLOAD_CHAT)

    if (getUnloadChatUser && enableChatting) {
        await processUnloadChat(getUnloadChatUser)
        await LocalStorage.removeItems(SB_UNLOAD_CHAT)
    }
    await skipOnNotification()
    while (bBotRunningStatus) {
        // will get the updated value if somethings get updated
        const { details } = currentSBPreset
        const { enableChatting = false } = details

        if (isManualScroll) {
            scrollFeed(true)
            isManualScroll = false
        }
        if (ownerDetails.owner_setting?.story_schedule_enable && stories.length > 0) {
            console.log('!!!!!!! start setStory')
            await setStory()
        }
        console.log('!!!!!!! start getDelayedChat')
        await getDelayedChat()
        console.log('!!!!!!! start checkSnapsAddCycleTimer')
        await checkSnapsAddCycleTimer()
        console.log('!!!!!!! start checkAddReloadTimer')
        await checkAddReloadTimer()
        if (enableChatting) {
            console.log('!!!!!!! start processMessages')
            await processMessages()
        }
        console.log('!!!!!!! start closeCurrentChat')
        await closeCurrentChat()
        await closeSnap()
    }

    feedDiv.removeEventListener('wheel', handleManualScroll)
}

const getDelayedChat = async () => {
    let currentValue = (await LocalStorage.getItem(KEY_SB_TIMERS_SET)) as SBTimerSetType
    if (currentValue?.delayed_users) {
        const furtherDelay: { [key: string]: string } = {}
        Object.keys(currentValue?.delayed_users).forEach(i => {
            if (!Utils.isTimePassed(currentValue?.delayed_users[i])) {
                delayedChatUserDisplayName.push(i)
                furtherDelay[i] = currentValue?.delayed_users[i]
            }
        })

        await LocalStorage.setItem(KEY_SB_TIMERS_SET, {
            ...(currentValue ?? {}),
            delayed_users: furtherDelay
        })

        if (Object.keys(furtherDelay).length !== Object.keys(currentValue.delayed_users).length) {
            lastCacheCheckOpenerUserList = []
            isUserListIterated = false
        }
    }
}

// will toggle the chat from cacheDisableChat on updating pause status from chat overlay
const handlePauseChatting = async (ruid: string, pause: boolean) => {
    if (pause) {
        setCacheDisableChatUser(ruid, {
            disabled: true,
            is_chat_disabled: true,
            ghost_message_count: 0,
            number_of_exchange: 0,
            phase: null,
            paused_chatting: true
        })

        console.log('@@@@@', cacheDisableChatUser)
    } else {
        delete cacheDisableChatUser[ruid]
        lastCacheCheckOpenerUserList = []
        isUserListIterated = false
    }
}
