import { LocalStorage } from '@/lib/chrome-storage'
import {
    sleep,
    waitForElement,
    waitForElementUnloadWithTimeout
} from '@/lib/common'
import { SB_UNLOAD_CHAT } from '@/lib/constants'
import { MessageType, threadMessageType } from '@/lib/types/scrape-engine.type'
import { closeCurrentChat, closeSnap } from '../closeCurrentChat'
import emojiStrip from 'emoji-strip'
import * as Utils from '@/lib/common'

export async function waitForContentToLoad() {
    const elementPromise1 = Utils.waitForElementTillLoad('.vDdE2.hJysT .b2f4R img.ChG6a')
    const elementPromise2 = Utils.waitForElementTillLoad('.vDdE2.hJysT .b2f4R video.nauoE')

    // load snap error
    const elementPromise3 = Utils.waitForElementTillLoad('.Fpg8t .VqwkQ .c12IS .tPHQ9.v0HEU')

    // no longer viewing loaded
    const elementPromise4 = Utils.waitForElementTillLoad('.Vbjsg.WJjwl ._XMCw .S4e9r .ecBYF .ejVI4 .RZoOk')


    // Wait for either of the promises to resolve
    const result = await Promise.race([
        elementPromise1.then(() => true),
        elementPromise2.then(() => true),
        elementPromise3.then(() => false),
        elementPromise4.then(() => false),
        new Promise((resolve, _) => setTimeout(() => resolve(false), 10000))
    ])

    return result
}

const getUserRole = msg => {
    let smsRole = null
    let currentElement = msg?.parentElement?.parentElement // Start 2 parents up

    for (let i = 0; i < 5; i++) {
        // Check up to 5 more parents, totaling 7
        if (!currentElement) break // Stop if there are no more parents

        const foundRole = currentElement.querySelector('header .GUB_w .nonIntl')?.textContent
        if (foundRole) {
            smsRole = foundRole
            break
        }

        currentElement = currentElement.parentElement // Move up to the next parent
    }
    return smsRole
}

const MAX_SEE_SNAP_ATTEMPTS = 3

export const openChatSnaps = async (skipWaiting = false) => {
    let attempt = 0
    const ruid = window.location.pathname.slice(1)
    if (!skipWaiting) {
        await waitForElement('._XMCw .ChLAv', 'chat-section', 10000)

        const isMainLoadUnload = await waitForElementUnloadWithTimeout(
            '._XMCw .ChLAv div.maLbV',
            30000
        )
        if (!isMainLoadUnload) {
            await LocalStorage.setItem(SB_UNLOAD_CHAT, ruid)
            window.location.reload()
            return
        }
        await sleep(500)
        const isLoadUnload = await waitForElementUnloadWithTimeout('._XMCw .ChLAv div.maLbV', 30000)
        if (!isLoadUnload) {
            await closeCurrentChat()
            await sleep(500)
            await LocalStorage.setItem(SB_UNLOAD_CHAT, ruid)
            window.location.reload()
            return
        }
        await sleep(500)
    }
    const messageDivElements = document.querySelectorAll('.KB4Aq.IPEgq')

    if (!skipWaiting && messageDivElements.length > 0) {
        const lastElement = messageDivElements[messageDivElements.length - 1]

        lastElement.scrollIntoView({
            behavior: 'instant',
            block: 'start',
            inline: 'nearest'
        })
        await sleep(500)
    }

    for (let msg of messageDivElements) {
        attempt = 0
        try {
            const isSnap = msg.querySelector('.vwM69 .AVVFt') as HTMLDivElement

            if (isSnap) {
                while (attempt < MAX_SEE_SNAP_ATTEMPTS) {
                    attempt++
                    if (
                        isSnap.innerText.toLowerCase().replace(/\s/g, '').includes('newsnap') &&
                        isSnap.innerText.toLowerCase().replace(/\s/g, '').includes('clicktoview')
                    ) {
                        const clickEvent = new MouseEvent('click', {
                            bubbles: true,
                            cancelable: true,
                            view: window
                        })
                        isSnap.dispatchEvent(clickEvent)

                        const success = await waitForContentToLoad()

                        if (success) {
                            attempt = MAX_SEE_SNAP_ATTEMPTS
                        }
                        await sleep(1000)

                        await closeSnap()

                        await Utils.sleep(1000)
                    }
                }
            }
        } catch (error) {
            console.log(error)
            return [] as threadMessageType[]
        }
    }
}

export const scrapeChatHistory = async (skipWaiting = false) => {
    const messages: threadMessageType[] = []
    const ruid = window.location.pathname.slice(1)
    if (!skipWaiting) {
        await waitForElement('._XMCw .ChLAv', 'chat-section', 10000)

        const isMainLoadUnload = await waitForElementUnloadWithTimeout(
            '._XMCw .ChLAv div.maLbV',
            30000
        )
        if (!isMainLoadUnload) {
            await LocalStorage.setItem(SB_UNLOAD_CHAT, ruid)
            window.location.reload()
            return
        }
        await sleep(500)
        const isLoadUnload = await waitForElementUnloadWithTimeout('._XMCw .ChLAv div.maLbV', 30000)
        if (!isLoadUnload) {
            await closeCurrentChat()
            await sleep(500)
            await LocalStorage.setItem(SB_UNLOAD_CHAT, ruid)
            window.location.reload()
            return
        }
        await sleep(500)
    }
    const messageDivElements = document.querySelectorAll('.KB4Aq.IPEgq')

    if (!skipWaiting && messageDivElements.length > 0) {
        const lastElement = messageDivElements[messageDivElements.length - 1]

        lastElement.scrollIntoView({
            behavior: 'instant',
            block: 'start',
            inline: 'nearest'
        })
        await sleep(500)
    }

    for (let msg of messageDivElements) {
        try {
            const stickerMsg = msg.querySelector('.p8r1z .rBYFf')
            const emojiMsg = msg.querySelector('.p8r1z span.ORkmz')
            const spanElement = msg.querySelector('.p8r1z > span.ogn1z.nonIntl')
            const isSnap = msg.querySelector('.vwM69') as HTMLDivElement

            if (isSnap) {
                if (
                    isSnap.innerText
                        .toLowerCase()
                        .replace(/\s/g, '')
                        .includes('rightclicktosave') ||
                    isSnap.innerText
                        .toLowerCase()
                        .replace(/\s/g, '')
                        .includes('rightclicktoreplayorsave')
                ) {
                    const smsRole = getUserRole(msg)

                    const messageElement = {
                        role: smsRole,
                        timestamp: Date.now(),
                        text: 'hey',
                        message_type: MessageType.SNAP
                    } as threadMessageType

                    messages.push(messageElement)
                }
            } else if (stickerMsg) {
                // replacing sticker with hey
                stickerMsg.dispatchEvent(new Event('mouseover', { bubbles: true }))

                const smsRole = getUserRole(msg)

                const messageElement = {
                    role: smsRole,
                    timestamp: Date.now(),
                    text: 'hey'
                } as threadMessageType

                messages.push(messageElement)
            } else if (emojiMsg) {
                // replacing sticker with hey
                const emoji = emojiMsg?.textContent
                emojiMsg.dispatchEvent(new Event('mouseover', { bubbles: true }))

                const smsRole = getUserRole(msg)

                const messageElement = {
                    role: smsRole,
                    timestamp: Date.now(),
                    text: 'hey'
                } as threadMessageType

                messages.push(messageElement)
            } else if (spanElement) {
                const sms = emojiStrip(spanElement?.textContent.trim()) || 'hey'
                spanElement.dispatchEvent(new Event('mouseover', { bubbles: true }))

                const smsRole = getUserRole(msg)
                const messageElement = {
                    role: smsRole,
                    timestamp: Date.now(),
                    text: sms
                } as threadMessageType

                messages.push(messageElement)
            }
        } catch (error) {
            console.log(error)
            return [] as threadMessageType[]
        }
    }

    messages.filter(i => !!i.role && !!i.text)
    return messages
}
