import * as Utils from '@/lib/common'
import { sendSnap } from './liveSnaps'
import { MessageType, threadMessageType } from '@/lib/types/scrape-engine.type'
import { cloneDeep } from 'lodash'
import {
    aiagentExecutionTime,
    currentSBPreset,
    setAiagentExecutionTime
} from '../..'
import { LocalStorage } from '@/lib/chrome-storage'
import { MESSAGE_SENT_SUCCESSFULLY } from '@/lib/constants'

const MAX_ATTEMPTS = 10
const RETRY_DELAY = 1000

export const dispatchMessage = async (
    message: string,
    performSendSnap: boolean = false,
    snapUrl: string = null
) => {
    const { details } = currentSBPreset
    const { settings = {} } = details

    try {
        if (message.trim()) {
            const msgChunked = Utils.multiLineChat(message)

            let isFirstMsgSent = false

            for (const msg of msgChunked) {
                const isUserPresent = checkIfUserIsPresentInChat()
                if (isUserPresent && settings.delayChatting) {
                    if (
                        !isFirstMsgSent &&
                        settings.delayChatting * 1000 - aiagentExecutionTime > 0
                    ) {
                        await Utils.sleep(settings.delayChatting * 1000 - aiagentExecutionTime)
                    } else {
                        await Utils.sleep(settings.delayChatting * 1000)
                    }
                    if (aiagentExecutionTime) {
                        setAiagentExecutionTime(0)
                    }
                }
                await writeMessage(msg)

                isFirstMsgSent = true
            }
        }
    } catch (err) {
        console.error(err)
        console.log('Fail send write message')
    }

    if (performSendSnap && snapUrl) {
        console.log(`Snap URL Received ${snapUrl}`)
        await sendSnap(snapUrl)
    }
    return true
}

const writeMessage = async (message: string) => {
    let attempt = 0

    while (attempt < MAX_ATTEMPTS) {
        attempt++
        try {
            const isLastMessageSent = await LocalStorage.getItem(MESSAGE_SENT_SUCCESSFULLY)
            if (typeof isLastMessageSent === 'boolean' && !isLastMessageSent) {
                throw new Error('Last msg not delivered yet')
            }
            const textAreaAwait = (await Utils.waitForElement(
                '.euyIb.nonIntl',
                'textarea',
                1000
            )) as HTMLTextAreaElement
            if (!textAreaAwait) {
                throw new Error('Text area not found')
            }
            textAreaAwait.textContent = ''
            textAreaAwait.dispatchEvent(new Event('input', { bubbles: true }))
            await Utils.waitForElementUnload('.IHV_t.v4zfr')
            textAreaAwait.textContent = message.trim()
            textAreaAwait.dispatchEvent(new Event('input', { bubbles: true }))

            const enterEvent = new KeyboardEvent('keydown', {
                key: 'Enter',
                code: 'Enter',
                keyCode: 13,
                which: 13,
                bubbles: true,
                cancelable: true
            })
            textAreaAwait.focus()
            await LocalStorage.setItem(MESSAGE_SENT_SUCCESSFULLY, false)
            textAreaAwait.dispatchEvent(enterEvent)
            return
        } catch (err) {
            console.log('####### error sending message:', err?.message)
            if (attempt > 5) {
                await LocalStorage.setItem(MESSAGE_SENT_SUCCESSFULLY, true)
            }
            await Utils.sleep(RETRY_DELAY)
        }
    }
}

const checkIfUserIsPresentInChat = () => {
    const userPresenceDiv = document?.querySelector('.kDi_7 .Hkh8C .icSM6 .FNfcp') as HTMLDivElement

    // if user have bitemoji, userPresenceDiv will have div with class .RTvji
    const hasBitEmoji = userPresenceDiv?.querySelector('.RTvji') as HTMLDivElement

    if (hasBitEmoji) {
        const isPresent = hasBitEmoji?.childElementCount > 0
        return isPresent
    }

    // if bitemoji is not preset, userPresenceDiv .TK1kc .T6Yjl
    const isUserPresent = userPresenceDiv?.querySelector('.TK1kc .T6Yjl') as HTMLDivElement
    return !!isUserPresent
}

function removeMyLastMessages(messages: threadMessageType[]) {
    let i = messages.length - 1
    let currentUser = null

    // Find the last non-"ME" user
    while (i >= 0 && messages[i].role === 'Me') {
        i--
    }
    if (i >= 0) {
        currentUser = messages[i].role
    }

    // Remove consecutive "ME" messages until a different user appears
    for (; i < messages.length; i--) {
        if (i < 0 || messages[i].role !== 'Me' || messages[i].role !== currentUser) {
            break
        }
    }
    if (i < messages.length - 1) {
        messages.splice(i + 1)
    }

    return messages
}

export const handleCombineMultiChat = (allMessages: threadMessageType[]) => {
    const opponentsLastMessage: threadMessageType[] = []
    let message: threadMessageType

    const messages = removeMyLastMessages(cloneDeep(allMessages))

    do {
        if (messages.length === 0) {
            break
        }
        message = messages.pop()
        if (message.role !== 'Me') opponentsLastMessage.push({ ...message })
    } while (message.role !== 'Me')

    if (opponentsLastMessage.every(i => i.message_type === MessageType.SNAP)) {
        return opponentsLastMessage[0]
    }

    const msg = opponentsLastMessage.reverse().reduce((prev, curr, index) => {
        prev = prev + (index === 0 ? '' : ' | ') + `${curr.text}`
        return prev
    }, '')

    return msg
}
