import { ApiResponse } from './types/response.type'
import { API_ENDPOINT, ServiceMessageName } from '@/lib/constants'
import { authStore } from '../store'

const snapRefine = async (presetId: number): Promise<ApiResponse> => {
    return new Promise(resolve => {
        const callback = response => {
            resolve(response)
        }

        chrome.runtime.sendMessage(
            {
                action: ServiceMessageName.FetchApi,
                params: {
                    url: `${API_ENDPOINT}/preset/snap/refine`,
                    params: {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            Authorization: authStore.getAPIKey()
                        },
                        body: JSON.stringify({preset_id: presetId})
                    }
                }
            },
            callback
        )
    })
}
export default snapRefine
