import { waitForElement } from '@/lib/common'
import { bBotRunningStatus } from '..'

export const closeCurrentChat = async () => {
    const backButtonClass = '.Vbjsg.WJjwl .enQRR.eKaL7.Bnaur'

    const backButton = (await waitForElement(
        backButtonClass,
        'close chat button',
        100
    )) as HTMLButtonElement
    if (!bBotRunningStatus) {
        return
    }

    if (backButton) {
        backButton?.click()
    }
}

export const closeSnap = async () => {
    const closeButtonClass = '.ecBYF .Hb2_Z .h9IpV'
    const closeButton = (await waitForElement(
        closeButtonClass,
        'close chat button',
        100
    )) as HTMLButtonElement
   
    if (closeButton) {
        closeButton.click()
    }
}