import { SBTimerSetType } from '@/lib/types/scrape-engine.type'
import { currentSBPreset } from '..'
import { LocalStorage } from '@/lib/chrome-storage'
import { KEY_SB_TIMERS_SET, ServiceMessageName } from '@/lib/constants'
import * as Utils from '@/lib/common'

export const checkAddReloadTimer = async () => {
    const { settings } = currentSBPreset.details ?? {}
    // returns if refresh value not set properly
    if (!settings?.autoRefresh) return

    const sb_timers: SBTimerSetType = await LocalStorage.getItem(KEY_SB_TIMERS_SET)

    const setNextReloadTimer = async () => {
        let delayOf = settings?.autoRefresh
        const timer = Utils.getNextTimer(delayOf)

        let currentValue = await LocalStorage.getItem(KEY_SB_TIMERS_SET)
        await LocalStorage.setItem(KEY_SB_TIMERS_SET, {
            ...(currentValue ?? {}),
            reload_cycle_timer: timer
        })
    }

    // snapchat reload trigger
    if (sb_timers && sb_timers.reload_cycle_timer) {
        const callNextCycle = Utils.isTimePassed(sb_timers.reload_cycle_timer)

        if (callNextCycle) {
            await setNextReloadTimer()
            window.location.reload()
            Utils.dummyClick()
        }
    } else {
        await setNextReloadTimer()
    }
}
