import * as API from '@/scripts/api'
import {
    currentSBPreset,
    setBotRunningStatus,
    setCacheDisableChatUser,
    setCurrentUserChatStatus,
    userMainInfo
} from '../..'
import dayjs from '@/lib/dayjs'
import { ERROR_MSG, ServiceMessageName } from '@/lib/constants'
import { messageParamsType } from '@/lib/types/chatting-overlay.type'

export const checkChatConversationStatus = async (uuid: string, name: string) => {
    try {
        const { details } = currentSBPreset
        const { settings = {} } = details

        const conversationStatus = await API.checkConversationStatus({
            request_user_id: uuid,
            snapchat_account_id: userMainInfo.mutable_username,
            model_id: currentSBPreset.model_id,
            allow_map: true,
            display_name: name
        })

        if (conversationStatus.status) {
            setCurrentUserChatStatus(conversationStatus.data)
            if (conversationStatus.data.disabled) {
                setCacheDisableChatUser(uuid, conversationStatus.data)
                return
            }
            if (conversationStatus.data.duplicate) {
                chrome.runtime.sendMessage({
                    action: ServiceMessageName.ChatOverLay,
                    params: {
                        uuid: uuid,
                        state: 'Duplicate'
                    } as messageParamsType['data']
                })
                setCacheDisableChatUser(uuid, conversationStatus.data)
                return
            }
            // add chat in cacheDisableChat and if user enable will remove using runtime message
            if (conversationStatus.data.paused_chatting) {
                setCacheDisableChatUser(uuid, conversationStatus.data)
                return
            }
            // add chat in cacheDisableChat as per dont reply after X days setting
            if (settings.dontReply && conversationStatus.data.created_at) {
                const talkBefore = Math.abs(
                    dayjs(conversationStatus.data.created_at).utc().diff(dayjs.utc(), 'days')
                )
                if (talkBefore >= settings.dontReply) {
                    setCacheDisableChatUser(uuid, conversationStatus.data)
                    return
                }
            }
        } else if (conversationStatus.message === 'User quota is not enough') {
            setCacheDisableChatUser(uuid, {
                disabled: true,
                is_chat_disabled: true,
                ghost_message_count: 0,
                number_of_exchange: 0,
                phase: null
            })
            chrome.runtime.sendMessage({
                action: ServiceMessageName.ForceOffBot,
                data: {
                    message: ERROR_MSG.TOP_UP_CONVERSATION_QUOTA
                }
            })
            return
        }
    } catch (error) {
        setCurrentUserChatStatus(null)
        console.error(`Failed to check UUID cache for user ${uuid}:`, error)
    }
}
