export const skipOnNotification = () => {
    const popupClassName = '._jsfs.fdBrb.lqq55.hPCRZ'

    const popup = document.querySelector(popupClassName)
    if (popup) {
        const notNowClassName = '.eCkjw .NRgbw.eKaL7.Bnaur'

        const notNow = popup.querySelector(notNowClassName) as HTMLButtonElement

        if (notNow) {
            notNow.click()
        }
    }
}
