import * as Utils from '@/lib/common'
import {
    getSnapSource,
    IS_LIVE_SNAP_LOADED,
    ServiceMessageName,
    StoryStatus
} from '@/lib/constants'
import { cameraHadLoad, currentSBPreset, stories, updateStories, userMainInfo } from '..'
import { dataURLToStream, renderImageFromBlob } from './chatting/liveSnaps'
import dayjs from '@/lib/dayjs'
import * as API from '@/scripts/api'
import { closeCurrentChat } from './closeCurrentChat'

export const setStory = async () => {
    const { details, id: presetId } = currentSBPreset
    const { timezone } = details
    const userTimezone = !!timezone ? timezone : Utils.deviceTimeZone

    for (let j = 0; j < stories.length; j++) {
        const i = stories[j]
        if (![StoryStatus.SENT, StoryStatus.SKIPPED].includes(i.status)) {
            const { id, caption, media_url, schedule_date } = i

            if (media_url && schedule_date) {
                const utcTime = dayjs.utc(schedule_date)
                const localTime = utcTime.tz(userTimezone)

                const now = dayjs().tz(userTimezone)

                console.log('@@@@@@ ', now.format(), localTime.format())

                if (utcTime.isToday()) {
                    const thirtyMinutes = dayjs.duration(30, 'minutes')
                    const hasPassed = now.isAfter(localTime.add(thirtyMinutes))
                    console.log('@@@@@@ out ', hasPassed)
                    if (hasPassed) {
                        await API.updateStory({
                            owner_id: userMainInfo.mutable_username,
                            select_preset_id: presetId,
                            story_id: id,
                            status: StoryStatus.SKIPPED
                        })
                        updateStories({ id: id, status: StoryStatus.SKIPPED })
                        break
                    } else {
                        const oneMinutes = dayjs.duration(1, 'minutes')
                        const hasPassed = now.isAfter(localTime.add(oneMinutes))
                        console.log('@@@@@@ in ', hasPassed)

                        if (hasPassed) {
                            const imageUrl = getSnapSource(media_url)

                            await closeCurrentChat()
                            try {
                                localStorage.removeItem(IS_LIVE_SNAP_LOADED)
                                console.log('send snap action started')

                                const response = await fetch(imageUrl)

                                if (response.status !== 200) {
                                    throw new Error('Unable to fetch image')
                                }
                                const blob = await response.blob()

                                if (cameraHadLoad) {
                                    window.postMessage(
                                        {
                                            action: ServiceMessageName.SendSnapBlob,
                                            data: { blob: blob }
                                        },
                                        '*'
                                    )
                                }

                                const startCameraButton = '.Jq_5_ .qJKfS'

                                const startCameraButtonAwait = (await Utils.waitForElement(
                                    startCameraButton,
                                    'start camera btn',
                                    3000
                                )) as HTMLButtonElement

                                if (startCameraButtonAwait) {
                                    startCameraButtonAwait.click()
                                }

                                const shotButtonClass = '.FBYjn.gK0xL.A7Cr_.m3ODJ'
                                await Utils.waitForElementTillLoad(shotButtonClass)
                                const cameraNotLoadedClass = (await Utils.waitForElement(
                                    '.CYQZP .mPxJQ.OqR8V .kbgiH .tPHQ9.v0HEU .nonIntl',
                                    'camera btn',
                                    3000
                                )) as HTMLButtonElement

                                const warningBar: HTMLSpanElement = cameraNotLoadedClass

                                if (
                                    !cameraHadLoad ||
                                    (warningBar &&
                                        warningBar.innerText === 'Could not load camera.')
                                ) {
                                    await Utils.sleep(2000)
                                    const dataURL = await renderImageFromBlob(blob)

                                    const spoofStream = await dataURLToStream(dataURL)

                                    const video = document.querySelector(
                                        '#local-video'
                                    ) as HTMLVideoElement
                                    try {
                                        if (video) {
                                            video.srcObject = spoofStream as MediaProvider
                                            video.muted = true
                                            await video.play()
                                            console.log('Video is playing')
                                        } else {
                                            throw new Error('No video element found')
                                        }
                                    } catch (err) {
                                        throw new Error(err)
                                    }
                                } else {
                                    await Utils.sleep(2000)
                                    await new Promise<void>((resolve, reject) => {
                                        let timeElapsed = 0
                                        const checkSpoofedStream = () => {
                                            const isSnapLoaded =
                                                localStorage.getItem(IS_LIVE_SNAP_LOADED)
                                            if (isSnapLoaded) {
                                                resolve()
                                            } else {
                                                timeElapsed += 300
                                                if (timeElapsed < 10000) {
                                                    setTimeout(checkSpoofedStream, 300)
                                                } else {
                                                    reject(new Error(`Issue loading snap`))
                                                }
                                            }
                                        }
                                        checkSpoofedStream()
                                    })
                                }

                                const shotButton = (await Utils.waitForElement(
                                    shotButtonClass,
                                    'shot_button'
                                )) as HTMLButtonElement

                                if (!shotButton) {
                                    throw new Error('Shot btn not found')
                                } else {
                                    shotButton.click()
                                }

                                if (caption && caption?.trim()) {
                                    const textClass = 'button.eUb32'
                                    const textBtn = (await Utils.waitForElementTillLoad(
                                        textClass
                                    )) as HTMLButtonElement

                                    if (!textBtn) {
                                        throw new Error('Text btn not found')
                                    } else {
                                        textBtn.click()
                                    }

                                    const textAreaClass = 'textarea.B9QiX'
                                    const textArea = (await Utils.waitForElementTillLoad(
                                        textAreaClass
                                    )) as HTMLTextAreaElement

                                    if (!textArea) {
                                        throw new Error('Text Area not found')
                                    } else {
                                        textArea.textContent = caption
                                        textArea.dispatchEvent(
                                            new Event('input', { bubbles: true })
                                        )
                                    }
                                }

                                const submitBtnClass = '.YatIx.fGS78.eKaL7.Bnaur'

                                const submitBtn = (await Utils.waitForElementTillLoad(
                                    submitBtnClass
                                )) as HTMLButtonElement

                                if (!submitBtn) {
                                    throw new Error('Shot btn not found')
                                } else {
                                    submitBtn.click()
                                }

                                const myStoryClass = '.lxJDC.zBw_I.DtbNU'
                                const myStory = (await Utils.waitForElementTillLoad(
                                    myStoryClass
                                )) as HTMLButtonElement

                                if (!myStory) {
                                    throw new Error('myStory btn not found')
                                } else {
                                    myStory.click()
                                }

                                const sendBtnClass = '.TYX6O.eKaL7.Bnaur'
                                const sendBtn = (await Utils.waitForElementTillLoad(
                                    sendBtnClass
                                )) as HTMLButtonElement

                                if (!sendBtn) {
                                    throw new Error('send btn not found')
                                } else {
                                    sendBtn.click()
                                }

                                await Utils.sleep(3000)
                                const closeBtnClass = '.MQv99 .AJ_5h'

                                const closeBtn = (await Utils.waitForElement(
                                    closeBtnClass,
                                    'close_button'
                                )) as HTMLButtonElement

                                closeBtn?.click()

                                await API.updateStory({
                                    owner_id: userMainInfo.mutable_username,
                                    select_preset_id: presetId,
                                    story_id: id,
                                    status: StoryStatus.SENT
                                })
                                updateStories({ id: id, status: StoryStatus.SENT })
                            } catch (err) {
                                console.log('err', err)
                            }
                            break
                        }
                    }
                }
            }
        }
    }
}
