import { API_ENDPOINT, ERROR_MSG, ServiceMessageName } from '@/lib/constants'
import { ApiResponse } from './types/response.type'
import { authStore } from '../store'
import { getUnusedParamsType } from './types/params.type'

const getUnusedSnap = async (params: getUnusedParamsType): Promise<ApiResponse> => {
    try {
        return new Promise(resolve => {
            const callback = response => {
                if (response.status)
                    response = {
                        status: true,
                        data: response.data
                    }

                resolve(response)
            }

            chrome.runtime.sendMessage(
                {
                    action: ServiceMessageName.FetchApi,
                    params: {
                        url: `${API_ENDPOINT}/snap-ids/verify`,
                        params: {
                            method: 'POST',
                            headers: {
                                Authorization: authStore.getAPIKey()
                            },
                            body: JSON.stringify(params)
                        }
                    }
                },
                callback
            )
        })
    } catch (error) {
        return {
            status: false,
            message: error?.message || ERROR_MSG.SOMETHING_WENT_WRONG
        }
    }
}

export default getUnusedSnap
